// 本程序自己的版本号。
//
// 为什么用「和游戏一致的版本」而不是 1.0.0 这类语义化版本：这个工具的推荐结论
// 完全取决于游戏当前的高难副本环境（黑塔网投稿是按游戏版本组织的）。用户拿到
// 一个版本号时，真正想知道的是「它对齐到游戏的哪个版本」，而不是内部改了几次。
// 所以主版本跟游戏走，末位是本工具自己的修订号：
//
//   v4.6.1  对齐游戏 4.6 环境，第 1 次修订
//   v4.6.2  同一游戏版本，第 2 次修订（神主日译名、成本优先级、跨模式综合结论）
//   v4.6.3  同一游戏版本，第 3 次修订（成绩写法改成游戏内实际的量：0T / 积分 / 行动值）
//   v4.6.4  同一游戏版本，第 4 次修订（启动后自动打开浏览器：探测不受系统代理与 401
//           影响、只监听 IPv6 也能等到、等待超时会明说；看门狗不再因读不到进程表而崩）
//   v4.6.5  同一游戏版本，第 5 次修订（关卡并进副本选择器：只有异相仲裁需要区分关卡，
//           单独一条会让控件行在一行/两行之间来回换行，整排控件跳 131px）
//   v4.6.6  同一游戏版本，第 6 次修订（外壳的 http 关联打不开浏览器时，改按真实路径
//           直接启动已安装的 Chrome / Edge，绕开注册表关联）
//   v4.6.7  同一游戏版本，第 7 次修订（抽卡推荐新增第一节「战斗记录」：米游社官方四个
//           副本的逐层队伍/回合/积分，并与榜单对照；成本单位统一改叫「金」）
//   v4.6.8  同一游戏版本，第 8 次修订（第一节改成四个副本按钮切换、只留最后一关；
//           点队伍里的角色可跳到角色信息页看它的面板；修骑士关排序与绝境量纲）
//   v4.6.9  同一游戏版本，第 9 次修订（第一节每间显示敌方——末日幻影/异相仲裁用官方
//           首领，混沌回忆/虚构叙事按档期对上黑塔网登记的那期；角色 chip 加头像；
//           点角色改为在本页弹面板，不再跳分页；撤掉榜单对照）
//   v4.6.10 同一游戏版本，第 10 次修订（浮层面板去掉技能等级；撤掉第一节的模拟宇宙与
//           公开主页卡片；敌方来源标签从「投稿口径」改成直接点名「黑塔网投稿」）
//   v4.6.11 同一游戏版本，第 11 次修订（祝福写出完整效果；每队标出金数；遗器补上
//           两件位面饰品（4+2）；撤掉顶部那排全局下拉框，副本/版本/预算挪进各自的
//           分节标题行；敌方不再挂来源标签）
//   v4.6.12 同一游戏版本，第 12 次修订（去掉队伍金数统计——限定/常驻会随版本变，
//           绝对金数容易误导；撤掉标题下那行小字；补上「本地数据集落后于游戏内
//           这一期」的提示，并把「换版本会自动适配什么」写进 README）
//   v4.6.13 同一游戏版本，第 13 次修订（成本口径按用户指定改成硬规则：4★、常驻 5★、
//           任意命途的开拓者、星芒商店光锥都不算成本，只有活动跃迁 5★ 才算；修正
//           免费光锥名单；第二节给出两个答案：每金收益最高 + 用满预算收益最大）
