//   v4.6.24 同一游戏版本，第 18 次修订（三处前端改动：① 默认权重按用户给定改成
//           绝境 10 / 其余四个 1；② 性价比徽标移到左边紧贴花费文字，悬停或聚焦
//           会展开算式明细（逐副本列权重、原始量、贡献）；③ 点战斗记录角色的浮层
//           补上角色立绘与光锥卡面 + 名字/标签 hero 区——原来传下去的是整份快照
