//   v4.6.25 同一游戏版本，第 19 次修订（用户点名的四条：① **性价比总榜与抽卡方案
//           的副本权重相互独立**——原界面上只有一行权重、两个榜互相绑架，现在
//           `WEIGHT_SCOPES = plan/frontier` 各一套覆盖（默认值仍是同一张表）、
//           API 收 `planWeights`/`frontierWeights`、界面两块各画一行输入框、各存
//           一份 localStorage；顺带修掉 `eidolonUnits` 在没传前沿表时静默按权重 1
//           算的旧 bug；② **两处入口弹出同一个角色浮层**——「角色信息」页点角色卡
//           原来直接抛 `ReferenceError: elementCn is not defined`（浮层根本弹不出来），
//           而且那一页的关闭按钮从来没接线过；现在浮层的关闭/背景/ESC 由
//           character-modal.js 自己接，两个入口连标题栏按钮都一样；③ **浮层里图片与
