//           ④ **开拓者及其各命途变体视为已拥有**——米游社只报当前那一个形态
//           （本机实测 id 8007 = 记忆），数据集按命途分成 5 个英文键，不补这一条会
//           让「只看我没有的」多列 4 条、上场率没有「已有」徽标、配队可达性折扣把
//           含开拓者的作业白打 0.25 折）
//   v4.6.26 紧凑角色详情浮层：缩小立绘、卡面、间距与卡片尺寸。
//   v4.6.27 遗器卡片增加图标；详情分区重排为桌面一屏，窄屏单列遗器并锁住浮层背景滚动；
//           立绘加载失败时让角色概览自动铺满，避免留下空列。
//   v4.6.28 角色页展示数据更新时间；账号侧栏去重；移除原神接口与格式适配；统一抽卡方案控件。
//   v4.6.29 修正角色属性字段解析；补充忆灵属性、有效词条统计与米游社式基础/追加/最终值展示。
//   v4.6.30 明确本地重读、黑塔网同步与米游社战绩刷新按钮语义，减少数据源混淆。
//   v4.6.31 推荐页标题栏显示黑塔网数据更新时间，同步完成后自动刷新时间记录。
//   v4.6.32 总榜权重与方案权重改为分层卡片布局，补充色彩区分与窄屏响应式换列。
//   v4.6.33 隐藏权重数字输入框原生 spinner，移除悬浮提示遮挡并补充无障碍标签。
//   v4.6.34 支持登录后继续添加米游社账号；保留账号独立凭证并可在侧栏切换、删除。
//   v4.6.35 角色详情里的光锥图标紧跟左侧文字信息，避免被推到 hero 面板最右侧。
//   v4.6.36 修复战斗记录刷新成功后继续落到 404 导致重复响应头的服务端错误。
//   v4.6.39 修正本体与关键星魂的证据隔离；按版本新近度与跨版本持续性调整前沿节点，
//           补齐限定光锥分类与默认满叠影规则。
//   v4.6.40 继续校正前沿归因：按载体星魂与同档光锥使用分布削弱整队强度对光锥的误归因，
//           对 E2/E6 里程碑增加数据驱动的目标档权重，并进一步衰减过时版本证据。
//   v4.6.41 统一页面总榜证据口径：绝境高星魂缺少低星魂支撑时降低 E0→E2 普遍性价比，
//           总榜浮层显示高星魂上限证据与光锥主流使用分布。
//   v4.6.42 修正多金目标成本曲线：4 金 E2→E6 不再只比 2 金目标增加少量成本压力，
//           取消 E6 额外统治力倍率，让高分质量与实际投入共同决定性价比。
//   v4.6.44：前沿只用服务端筛选后的达标/满分记录；同一单位按独立赛季与配置
//           校正偶然极端投稿；取消帕累托层二次惩罚；按载体替代率校正光锥归因。
//   v4.6.43 简化总榜模型：E2/E6 各看自身高分前沿证据，成本按真实金数线性计入，
//           移除低星魂前置折扣与目标档额外倍率，避免社区常见 E2 节点被系统性低估。
//   v4.6.38 总榜改为数据驱动的高分节点评分：按绝对高分、帕累托层、共享队伍
//           归因与可配对的目标档断点综合计分；缺少低档样本不扣分，光锥成本仍按 67 抽。
//   v4.6.45 性价比总榜改成**整包口径**（用户 2026-10 原话：「不用单独分析角色/星魂/
//           光锥，也不考虑某个星魂的造价，而是把整个角色打包比较，比较的内容仅考虑
//           队伍的整体强度」）。单位 = 角色 + 星魂目标档 + 光锥（含叠影）绑成一条，
//           分子分母都只来自那支**队伍**：
//             分 = 100 × 档位权重 × 行动值项 × (该副本最便宜金数 ÷ 该配置金数)
//           整包自己的金数只用于展示。用户给的判据实例在真实数据上复现：
//           银狼LV.999 E2S1（7 金队） > 砂金·戏浪 E6+非限定光锥（9 金） >
//           砂金·戏浪 E6+专武 S1（10 金，与前者同一队、只多一把专武）。
//           **刻意移除**：v13/v14 加进来的「版本新近度衰减」与「独立赛季/配置可靠性
//           折扣」不再进分数（与「只看队伍强度和金数」不相容），降级为展示字段；
//           「光锥按 67 抽计价」也不再影响总榜（金就是金）。同一支队伍的成员必然
//           同分 —— 这是口径的直接推论，用户明确接受并列、不再加二级排序键。
//           界面同步：总榜按星魂档筛选、每行新增「最佳证据」一行与并列标记、
//           浮层改讲队伍；顺带修掉总榜一直显示英文数据集键的老 bug（只认 nameCn，
//           而总榜一路没有这个字段）。结论载荷形状升到 payload: 4。
//   v4.6.46 整包口径第二轮（用户 2026-10 的十二条要求）。落地九条：① 每个角色在榜上
//           只出场一次（只留分数最高的整包，榜面 1090 → 65）；②⑥⑦ 加版本维度 ——
//           近 1-3 个版本各 2 分、近 4-7 个各 1 分（窗口 7，权重按「距最新版本几个
//           版本」现算，黑塔网出新版本自动生效），缺证据的版本按场地水平等比例放大；
//           ⑧ 修掉叠影读取缺陷 —— 站点用「叠影 0」表示没装光锥，旧代码 `Number(x) || 5`
//           把 0 读成满叠影 SI5，实测 7,715 个前沿位置被凭空写成 S5（队伍金数没被污染，
//           污染的是整包打包键）；⑩ 同金数时限定光锥多者更强；②③④⑤ 界面：总榜行带
//           角色头像与光锥图标、「最佳证据」悬停弹出带图配队卡片、去掉「差这一档」、
//           「赛季」改叫「版本」。⑨⑪⑫ 是「现状正常、不要动」。
//   v4.6.47 修掉 v4.6.46 版本放大口径的三处错误（用户 2026-10 追问「4.2 版本权重为何
//           这么高」时定位）。错法：对所有缺证据的版本放大（不只旧版本）、没有「登场」
//           概念、参考版本取「该整包最佳证据所在版本」。后果：锚在 4.2（场地水平七版
//           最高）的整包对 4.3~4.6（**比它更新**）也吃 2 倍上限，分数被抬高 1.71 倍
//           （艾丝妲 E6：1516 → 885 = 它的实测分），榜面前排清一色「4.2 版本」证据，
//           而那条实测分只占加权和的 5.8%。现在只有**早于该整包登场版本**的旧版本才
//           放大（登场版本 = 角色与光锥里较晚登场的那个，建库时扫全部 29,769 条投稿
//           算出 refs.firstSeen），比登场更晚的缺失版本只按实测分中性估计。榜面变回
//           当前版本有实测证据的强角：银狼LV.999 E2 1180（4.6）> 真珠 E2 1167（4.6）
//           > 砂金·戏浪 E6 1132（4.6）。同时修掉界面浮层那条「其中 N 个版本为推算」
//           永远不显示的 bug（服务端从未投影 estimatedSeasons）。
//
//   v4.6.48 修「性价比总榜的版本窗口锚在被回退的版本上」这处口径 bug（用户 2026-10
//           报告「砂金·戏浪在性价比总榜的排名偏低」时定位）。`listEnvs` 的完整性回退
//           （最新可靠版本投稿 < 上一版的 60% 就退回一版，本意是别拿半收集的新赛季当
//           **基线**）顺手也决定了压金前沿的**版本窗口锚点**，而 `archiveFrontier` 的
//           窗口是 `seasons.slice(idx - window + 1, idx + 1)` —— 锚点一回退，比它更新的
//           版本就**整个掉出窗口**（不是降权，是删掉）。实测 4.6 的异相仲裁有 591 / 230
//           条投稿（远超下限 20），却因为「只有 4.5 的 48%」被回退：砂金·戏浪在 4.6 的
//           9 金满分证据被 4.5 的 11 金证据顶替，绝境贡献 887 → 661，名次 #2 → #14。
//           现在拆成两个版本：`season`（主证据，可回退；服务基线 / 抽卡方案 / 差距榜）
//           与 `frontierSeason`（前沿窗口锚点，只受 minSeasonRuns 约束、不回退；服务
//           性价比总榜）。环境构建抽成 `conclusionEnvs`，生产与 tools/ 的探针共用 ——
//           探针以前各写一套选取（且不传 firstSeen），「探针说 #3、界面是 #14」正是
//           这么来的。修复后榜面：真珠 E2 1050 > 砂金·戏浪 E6 887 > 千冶·刃 E0 854 >
//           银狼LV.999 E2 797；抽卡方案的 units / envs 载荷逐字节不变（已实测对比）。
//
//   v4.6.49 性价比浮层改成「贡献值来源」口径（用户 2026-10 原话：「要在性价比界面列出贡献
//           值来源，要更简略的文字描述」）。改前浮层给的是「一行算式 + 7 段两~三行的解释」：
//           读者看得到 +660，看不出这一坨是怎么乘出来的。现在逐副本把它拆成
//           **权重 / 档位 / 行动值 / 金数 / 版本** 五个因子，乘起来精确等于「贡献」那一列
//           （多副本时多一行「合计」= 徽标上的数），文字压成 6 条**单行**脚注。
//           因子由 `frontierFactorsOf()` 现算 —— 与算分共用同一批 `SCORING` 常量与
//           **同一对行动值分位边界**（`avLo` / `avHi` / `lowerIsBetter` 随 `frontierEnvs`
//           一起下发：拿 `minAction` / `maxAction` 算会和榜上的分对不上），界面不抄第二份
//           公式（抄一份就会在该改口径时悄悄说谎）。回归：`herta-test.mjs` 在夹具上钉死
//           五个因子的取值、在真实数据上逐行断言「因子乘回去 = 榜上的分」；
//           `check-advice-layout.mjs` 断言来源表是那七列且没有 NaN、脚注 ≤60 字、
//           整块仍在可见区内。浮层宽度上限 560 → 600，来源表加 `min-width: 560px`，
//           否则「异相仲裁 · 绝境王棋关」会被挤成「…绝境王棋 / 关」。
//
//   v4.6.50 「贡献值来源」浮层的可读性（用户 2026-10 在本机连提四条）。来源表整表**居中**
//           （改前 th / td 都是右对齐，宽度不一的格子会从表头左边「探出去」，看着不像落在
//           同一列下面）；因子不再用乘号把「原始量」和「系数」**相互连接**，改成空格分隔、
//           系数一律括号起来 —— 档位 `满分 （1.00）` / 行动值 `299 （0.88）` /
//           金数 `7÷9 （0.78）`；只有系数、没有原始量的权重 / 版本仍是 `×10` / `×1.03`
//           （那个乘号不连接任何东西，而且正是「这是一枚乘数」的提示，与抽卡方案浮层一致）。
//           「贡献」列改成**完整乘法链**（用户原话：「贡献应当写出真实的计算过程」）：
//             `10 × 100 × 1.00 × 1.00 × 0.70 × 1.50 = +1050`
//           改前那一格只有一个结果数，读者拿可见的因子相乘只得 10.5 —— 链子里那枚隐形的
//           `×100`（`SCORING.frontierPackScale`）从界面其余字段反推不出来，所以
//           `frontierFactorsOf()` 的返回值补了 `packScale`。链子的因子文本复用各列同一个
//           `factorText()`，界面仍然不抄第二份公式。
//           ⚠️ 已知残留：因子按两位小数显示，手算末位可能与结果差 ≤1%（实测最差的一行是
//           `0.88 × 0.78 × 1.30` 乘出 892、而结果是 887）。浮层宽度上限 600 → 760px
//           （贡献列从 ~44px 涨到 ~250px），`tableW ≤ clientW` 那条 CDP 断言需在真浏览器
//           里复核一次（本机 Chrome 在会话内起不来，本轮没跑成）。
//
//   v4.6.51 性价比浮层的**排版**（用户 2026-10「优化排版」，只动 `public/`，口径不变：
//           `frontierFactorsOf()` 的取值与榜面一字未改，改完 `herta-test.mjs` 仍全绿）。
//           改的是这四件：
//           ① **因子列上下两行**（`tipFactor()`）：改前 `满分 （1.00）` 是一行，六个因子列
//              各自被那半截括号撑到 ~90px，七列加起来比「贡献」列还宽，第一列的副本名被
//              压成「异相仲裁·绝境王棋 / 关」这种落单断字。现在主值一行、系数小号退到弱化
//              色一行，列宽只由主值决定（`满分`/`226`/`7÷10` 都很窄）。
//           ② **副本名按 `·` 拆两行**（`tipEnvLabel()`）：中文可以在任意两字之间断开，
//              断行位置交给浏览器就一定是难看的那个。现在副本名小号弱化、关卡名正常对比，
//              两段各自 nowrap。
//           ③ **乘法链与结果分层**（`tipChain()`）：链是说明（小号弱化、可折行），
//              `= +1050` 是答案（金色加粗、永不折行）。改前两者同色同行，视线要先横穿整条
//              链才看得到结果。
//           ④ **脚注收成两栏**（`.advice-value-tip-notes`，`columns: 2`，窄屏回落单栏）：
//              六条各自是浮层直接子节点时一眼过去是一堵灰字墙。每条仍是独立的
//              `.advice-value-tip-note` —— `check-advice-layout.mjs` 按这个 class 数条数、
