//           浮层不再横跨小半屏，也终于不必靠「加宽」来买第一列不断字。
//           ⚠️ 这两条数值有 CDP 断言盯着（`tableW ≤ clientW`），改完必须在真浏览器复核 ——
//           本轮实测：浮层 620×329px、来源表 594px、整块在可见区内、无横向滚动。
//
//   v4.6.56 **已登场却缺证据的版本算 0 分**（修正 v4.6.53 的口径，用户 2026-10-10
//           「应该算0分，**没排名说明完全无人使用**」）。
//           ⚠️ v4.6.53 把这类版本实现成「权重**不进分母**」，那是错的，用户明确否掉：
//           **「完全无人使用」不是「未知」，而是「明确的差」** —— 一个整包在它已经存在
//           的版本里没有任何人用，说明它在那个版本确实不受认可。把明确的差当成不知道，
//           会让「只在某一版能用」的整包凭空拿到接近满分的成绩。实测那个错版**分数不降
//           反升**：绝境的分母从 10缩到 1，那一栏还恰好显示 ×1.00，像「七版一致地强」。
//           ① 现在分三种：**有证据** → 实测分；**缺证据且早于登场** → 第 6 条的等比例
//              放大；**缺证据且已登场** → **算 0 分**（`wSum += w` 但分子不加）。
//              实现只差一行，但语义完全不同。
//           ② 实测差异（开拓者•记忆 E6 + 愿虹光永驻天空S1，异相仲裁·绝境）：
//              错版 777 分 / 第 6 名 → 本版 **336 分 / 第 15 名**；
//              逐副本贡献 708/37/21 → **277/22/17**。榜首真珠 E2 1050 → 910。
//           ③ `droppedSeasons` 的措辞改成「已登场却无人使用，算 0 分」——
//              「无效成绩」会被读成「数据缺失」，而它其实是「明确的差」。
//           ④ 「版本因子」重新变回**折扣**（恒 ≤ 1）：它表达「观测到的版本里有多少被
//              无人使用拖低了」。v4.6.53 那一版它恒等于 ×1.00，等于什么都不反映。
//           实测全榜：无人使用版本 **653**、仍走推算 101、有观测 492，条数不变（67）。
//           ⑤ 顺带修「证据广度只展示」那条用例的**夹具**：它原来让两个整包**版本覆盖
//              不同**（Solo 1 版 / Widely 2 版），于是在测「版本覆盖影响分数」而不是
//              `configCount`。现在版本覆盖相同、只差配置条数。
//              （`configCount` 数的是**不同阵容键**的条数 —— 两条记录队友相同只算 1 条，
//              写夹具时要注意。）
//           回归：`herta-test.mjs` **78 项**全绿（核心断言钉死 `100×2÷(2+2)=50`：
//           误改成「中性补」或「不进分母」都会得到 100，只有 50 咬得住）；
//           `e2e-test.mjs` 110 项全绿。`tools/_probe-version-factor.mjs` 同步改了——
//           它独立重算一遍再与生产对账，规则不改就会打出「✗ 不一致」。
//           ⚠️ 服务端改动的生效条件：`src/**` 必须**重启** `bin/serve.mjs`。
//
//   v4.6.52 **联网策略反转**：默认不联网（用户 2026-10「此项目不需要每次刷新都去更新
//           数据，过多的请求会导致数据爬取出错」）。评分口径与界面排版**一字未改**，
//           `herta-test.mjs` 那 76 项仍全绿；改的只是「什么时候才允许打米游社」。
//           ① **判定从「看 TTL」改成「看有没有本地数据 + 是不是显式刷新」**
//              （`cache-policy.js` 的 `createRefetchGate`）。改之前是「快照超过 15 分钟、
//              战斗记录超过 30 分钟就自动重抓」——于是**每刷新一次页面、每切一次抽卡
//              推荐页**都会自动打一次米游社。米游社风控（10041「当前账号存在风险」/
//              5003/1034）按请求频率累计，触发就是小时级临时限制，而且越反复刷新恢复越慢。
//              用户看到的症状就是「数据爬取出错」。现在有本地数据时读取一律不联网。
//           ② **唯一保留的自动联网**：本地一份数据都没有时（首次使用、换了新角色）仍抓
//              一次，否则界面只能空白。这是有意的例外，本工具的价值就是看自己的角色。
//           ③ **显式刷新也限流**：两次真实请求至少隔 60 秒，按「账号/角色/资源」分计
//              （`MIN_REFETCH_INTERVAL_MS`，可用 `DSH_HSR_MIN_REFETCH_INTERVAL_MS` 覆盖）。
//              连点按钮会被挡下并**直接返回本地那份**，回 `throttled` + `retryAfterMs`；
//              尝试时间记在「决定联网」那一刻而不是请求成功之后——风控不因为我们失败
//              就少算一次配额。限流命中且本地无数据可退回时回 **429** 而不是 200+空数据，
//              否则界面会显示成「这个角色没有数据」，真实原因却是「刚请求过、太密了」。
//           ④ **界面上把这件事说透**：更新时间那行改成「· 本地缓存（不会自动联网更新，
//              点「刷新米游社战绩」取最新）」+ 悬停说明；战斗记录那节也补一句来源说明。
//              以前 cached 时会弹一次 toast，现在那是**默认路径**、每次开页面都会走，
//              弹一次就成了噪音，所以撤掉（信息挪进常驻的那行）。
//              刷新按钮在限流窗口内**变倒计时并禁用**（`advice-view.js` 的 `armThrottle`），
//              连点这个动作在按钮层面就发生不了。
//           ⑤ `CACHE_TTL_MS` 保留但**降级为纯显示**：只决定界面要不要提示「数据偏旧」，
//              不再决定发不发请求；数值从 15/30 分钟放宽到 6 小时（按分钟划线的话提示
//              会一直亮着，变成噪音）。
//           回归断言（`e2e-test.mjs`，本轮**反转**了一条旧断言）：
//           `stale snapshot is served locally WITHOUT refetching` /
//           `expired records cache is served locally WITHOUT refetching` /
//           `immediate second refresh is throttled`。
//           ⚠️ 服务端改动的生效条件：`src/**` 必须**重启** `bin/serve.mjs` 才生效
//              （`public/` 刷新即可）。忘了重启的症状：连点刷新仍然不会被限流。
//
//   v4.6.57 **「该角色的全部配装」放进性价比浮层**（用户 2026-10-10 澄清：
//           「不是在角色面板显示，而是在性价比面板显示，角色面板要恢复旧版原样」）。
//           ⚠️ **v4.6.55 做错了地方**：那一版把配装块加进了 `character-panel.js`
