//              `--only=previews` 单独拉）。断点续传，`--dry` 可先看体积。
//              **不入 git**（可再生资源，见 .gitignore）。
//           ② `archive.js` 的 `localizeIconUrls()` 把图标 URL 改写成
//              `/icons/<相对路径>?fallback=<原CDN地址>`：**只改 URL 不改键**，
//              所以 `resolveIcon()` 的四级兜底照常成立。**没镜像也照常工作**
//              —— `app.js` 的 `/icons/*` 路由在本地缺失时 **302** 回 CDN。
//           ③ 图标**不参与 `authorize`**：`<img src>` 不会带自定义请求头，
//              带令牌检查就全挂。走长缓存 `immutable`（实测本地 200 时
//              `max-age=604800`），免得每次开浮层都重问一遍。
//           ⚠️ 顺带修了一个**真 bug**：浮层里原先 112 张图有**15 张没有 src**
