//
//   v4.6.58 新鲜度提示按用户要求收敛（用户 2026-10 看了界面截图后提两点，
//           都只动**显示**，`CACHE_TTL_MS` 依旧不决定发不发请求、口径与排版未动）：
//           ① **7 天内不提示「过期/旧数据」**。新鲜窗口从 6 小时放宽到 **7 天**
//              （`cache-policy.js` 新增具名常量 `FRESH_WINDOW_MS = 7d`，两个 TTL 都取它）。
//              截图里那份数据是 **11 小时**前抓的，却顶着「过期/旧数据」红字 —— 那正是
//              v4.6.52 把窗口从 15/30 分钟放宽到 6 小时留下的后遗症：改成读本地之后
//              数据只在手动刷新时变新，按小时划线必然让提示一直亮着。
//              演进别再往回调：15/30 分钟（自动重抓时代）→ 6 小时 → **7 天（当前）**。
//           ② **「分区：index·新鲜 basicInfo·新鲜 …」整行去掉**（用户原话：
//              「不要写分区是否新鲜」）。它一次列七八个分区各带一个状态词，但用户
//              用不上：数据是整份一起抓的，某分区「不新鲜」不会让他多做什么 —— 想更新
//              只有一个动作，就是点「刷新米游社战绩」。连带的 `.freshness-sections` /
//              `.freshness-section` 样式（app.css 13 行）一并删掉，不留死代码。
//           ③ 顺带把「有效至 / 服务端未声明过期时间」那半句也收进**真的过期才显示**：
