//              判定（有分区抓失败时那条「原因」提示是有用的），只是不再单独画出来。
//           回归：`cache-policy-test.mjs` 钉住 6 天 23 小时不 stale / 7 天整才 stale，
//           `e2e-test.mjs` 的 `served snapshot reports how old it is` 同步改成新语义
//           （⚠️ 它上一轮断言的是「90 小时前 = stale=true」，在 7 天窗口下必须反转）。
//
//   v4.6.68 **「S叠影」与「N 金」之间加真实间隙**（用户 2026-10-10 第 8 轮：
//           「s1 和 8 金应该隔开一点点」）。**纯显示层，评分口径一字未改。**
//           ① 根因：中间那个分隔符是个**没有 class 的 span**，值 ` · ` 两侧的空格被
//              HTML 折叠掉 —— 实测 `S5` 右缘到 `3 金` 左缘只有 **2.9px**（就剩「·」
//              一个字符），看着像「S5·3 金」。上一轮刚给「+」解决过同一个坑
//              （`.advice-unit-plus` 的 `white-space: pre`），这次轮到分隔符。
//           ② 修法：给它类名 `.advice-unit-sep` + `white-space: pre`（app.css），
//              两侧空格真的占位 → 实测间隙 **2.9px → 10px**（67 行全部一致）。
//              ⚠️ 别改成给 `.advice-gold` 加 `margin-left`：那样 `textContent` 里就没
//              分隔符了，CDP 的花费形状断言 `/^(\+ .+ · )?\d+ 金$/` 会判红。
//
//   v4.6.69 **性价比得分算法审计：修 2 处口径 bug + 合并档位/行动值 + 修面板分数不一致**
//           （用户 2026-10-11：「检查此程序的性价比得分的算法是否存在不足」，
//            随后逐条指定修复范围）。本轮共 6 项，其中 4 项改了算分。
//
//           ① **缺陷 1（口径 bug）**：「已登场却无人使用 → 算 0 分」的判定基准是
//              **截断后的前沿池**，不是「有没有人用」。`pack.bySeason` 只从
//              `frontierRows`（已按成本砍到最便宜 25%）建，于是「有投稿但没挤进
//              最便宜前沿」被误判成「完全无人使用 → 0 分」。文档 v19 **自己写过**
//              「『不使用』与『使用但没进最便宜 25% 前沿』是两件事」——实现没落实。
//              修法：`archiveFrontier` 新增 `observedPacks`（**未截断**的观测集，
//              只走服务端内部，不下发浏览器），三态判定改用它；新增第四态
//              `unrankedSeasons`（有人用但没进池 → **不参与平均**，不可观测）。
//              实测：算 0 分从 492 → 308（去掉的 184 个都是「其实有投稿」的误判）。
//
//           ② **缺陷 2（口径 bug）**：金数项的分母**混了档位**。文档说「达到
//              **最好一档**的最便宜那支」，代码却 `minCostBySeason` 不分 tier、
//              直接取该版本所有行最小 → target 档更便宜时把 perfect 档系统性压低。
//              实测 `aa/plight` **6/7** 个版本被拉低（4.6 的 perfect 9 金被写成 8）、
//              `as` 3/6、`aa` 2/7。修法：分母改取**该版本 perfect 档**的最小金数
//              （缺 perfect 档才退回全档最小）。榜面 31/67 条分值变、名次基本不动。
//
//           ③ **缺陷 3（设计缺陷，按推荐方案合并）**：「档位」与「行动值」是**同一
//              维度被乘了两次** —— 档位本身就是拿成绩与判据线比出来的。实测后果：
//              两因子高度相关（乘积 ≈ 平方），且**跨判据线时跳变 2.0~2.3 倍**
//              （绝境满分线两侧 0.876 → 0.437，而成绩只差几个行动值）。
//              修法：新增 `perfFactorOf()` —— 以**游戏内判据线为唯一标尺**做一条连续
//              单调曲线：满分线处 = 1.00、达标线处 = 0.50（**与旧档位权重在线上完全
//              一致**，口径没变）、线之间线性过渡，达标线外继续衰减到地板
//              `frontierPerfFloor = 0.05`。三条性质保证兼容：线上取值不变、
//              上界仍是 1.00（`frontierPackScale = 100` 的量纲不变）、每副本用自己的
//              线（跨副本可比）。**顺带修掉一个隐藏问题**：旧口径用「该副本前沿池的
//              5%~95% 分位」归一化，而混沌回忆人人 0T → 区间退化 → 行动值项恒 = 1，
//              权重第二高的副本里这一项**完全失去区分力**；新口径以判据线为标尺，
//              不再依赖样本分布。界面随之把 7 列合并成 **6 列**（新增「表现」列）。
//
//           ④ **缺陷 4**：「最便宜 25%」实际纳入 **28%~33%**（`cut = costs[floor(n×pct)]`
//              后取 `r.c <= cut`，成本是离散小整数 → cut 上的并列整批纳入；
//              极端情况（金数全同）会纳入 100%，筛选完全失效）。修法：改成按数量
//              **严格**取 `floor(n × pct)` 条（排序键 = 金数 → 行动值 → 阵容键）。
//              实测 5 个副本全部精确 25.0%。
//
//           ⑤ **缺陷 5（不改算法，改可见性）**：「早于登场 → 不参与平均」让新角色只按
//              它唯一那一版算（近似**单点最大值**），老角色按 7 版加权平均（被没上榜
//              的版本拖低）—— 实测观测 1 版的 max=80、观测 7 版的 p50≈30。按用户第 6 条
//              「**不罚**新角色」的明确口径**不动算法**（向均值收缩会与之冲突），
//              改为在浮层加一条脚注写出**实测证据数**（`N 个（副本×版本）`），
//              让读者自己判断可信度。
//
//           ⑥ **缺陷 6（死代码清理）**：`SCORING.reachBeta` / `frontierHighscoreFloor`
//              全仓零引用，已删除；`frontierTeamScore` / `paretoFrontier` /
//              `paretoLayers` 在生产链路（`src/` + `public/`）**零引用**（只在
//              `herta-test.mjs` 被调用）—— 文档 v9/v14 描述的「成本/行动值帕累托分层」
//              **从未生效**，保留导出（不破坏公开 API）但加显著弃用标注。
//
//           ⑦ **截图 bug（用户直接报的）**：同一支队伍（砂金·戏浪 E6S1 + 向浪花掷下
//              盛夏S1，绝境 11 金 / 行动值 285）在总榜浮层显示 **+399**、在角色面板
//              显示 **+725**，比值 1.817 ≈ 10 ÷ 5.5 正好是权重之比。根因：
//              `/api/archive/packs` 路由只传 `window`、**没传 `frontierWeights`**，
//              前端 `fetchPacks` 也没带 → 面板永远按**默认权重**算，而浮层用的是用户
//              在界面上定的「总榜权重」。修法：路由从查询串读 `frontierWeights`、
//              前端带上它并把权重并进缓存键（否则改权重后仍吃旧结果）。
//              实测修复后两侧一致（468.1849）。
