//           **等高**」。两处都是纯排版：
//
//           ① **文字等高**：`.advice-value-tip-table td` 的 `vertical-align` 从 `middle`
//              改成 `top` —— 第一列因为要塞 4 张卡片而很高，别的列原先在那一行里**居中**，
//              于是「×10 / 299 / 9/9」比同行的「绝境王棋关」低十几像素，一行读不成一条线。
//              同时把 `tipEnvLabel()` 的**副本名 + 关卡名并到同一行**（`.tip-label-title`，
//              中间那个 `·` 由 `.tip-label-dot` 画出来）：改前是竖排三行（副本 / 关卡 /
//              版本），并排之后第一行就是这一行的标题、与其余各列齐平，还少一行高度。
//              两段仍**都在**，所以「异相仲裁下两个关卡会混起来」这个理由不受影响。
//           ② **图标往右分散**：`.tip-label-cell .advice-team` 从 `center` 改成
//              `space-evenly`，并给 `.tip-label-cell` 与它里面的 `.advice-plan-team-slot`
//              加 `width: 100%` —— 这两个都是**按内容收缩**的 inline-flex 元素，只改
//              `justify-content` 是没用的（没有可均分的余量，这正是改前卡片挤在中间、
//              左右各留一大块空白的原因）。实测改前铺开比例约 0.72、改后应 ≥0.9。
//
//           新增两条**量几何**的 CDP 判据（都并入 `teamBlockOk` ⇒ 计入 `failures`）：
//             · 「等高」：用 `Range` 取每一格里**第一段文字**的实际顶边，第一格与同一行
//               其余各列文字顶边的偏差必须 ≤4px（回到 `middle` 会差几十像素）；
//             · 「分散」：卡片行算出来的 `justify-content` 必须是 `space-evenly`，
//               且四张卡实际铺开（首张左边缘 → 末张右边缘）占该格宽度 ≥80%。
//           结构探针 `tools/_probe-tip-structure.mjs` 同步加验「副本名与关卡名在**同一个**
//           `.tip-label-title` 里」。
