//   v4.6.84（同一支 worktree 分支 `fix/cap-basis`）：用户看完三池对照后拍的两条口径变更 ——
//           **候选池放宽 + 差额封顶改成 p75**。
//
//           起因是用户的一句判断：「任何队伍都应该有机会参与竞争，哪怕这支队伍本身实力
//           不强，但可以依靠性价比拉分，结果很有可能名列前茅」。数据证实了它：
//           第七轮修掉的是「先按队分初选前 N 支」那道闸门，**候选池本身还有第二道** ——
//           池 = 「性价比总榜按队伍去重」= 每个角色只留**总分最高**的那一个整包，于是
//           同一支队伍的**低配档位会被它自己的高配档位挤掉**，池里只剩最贵的那版。
//
//           ① **候选池：总榜 → 逐档榜 ∪ 总榜**（`teamPoolUnits()`，新增导出）。
//              逐档榜 = 「每个角色 × 每个星魂档（E0/E1/E2/E6）各收敛一条」。实测账号 1：
//              池 **78 → 245** 支；用户最初关注的那支 `白厄/昔涟/刻律德菈/花火`（补 2 金）
//              在总榜池里**根本不存在**（只剩补 6 金的高配版），换池后进到 **#10**；
//              前 15 名里有 8 支是总榜池拿不到的。
//              ⚠️ 并集里的总榜那一半是**保险**：`byTier` 按 `eidolon` 精确相等过滤，
//              档位表只有 0/1/2/6，所以结构上「最佳整包落在 E3/E4/E5 的角色」只在总榜里。
//              实测当前数据集没有这种角色（总榜 84 条的 key 全在逐档榜里，并集不多带一支），
//              留着是挡这个结构缺口 —— `team-plan-test.mjs` 有一条不变量钉它。
//              ⚠️ 逐档榜**本来就在载荷里**（星魂档筛选 chips 要用），266 条全部带队友名单，
//              所以这次放宽是**客户端单方面**的，**载荷一个字节都没涨**（仍 520 KB）。
//              **没选**「全部整包」（2453 条 / 2179 支）：那批绝大多数是一次性投稿，
//              ① 趋近 0，实测账号 2 前 15 名里 12 支是「补 1 金 + ① 个位数」的噪音；
//              而且体积 888 KB，直接超 e2e 的「载荷 < 600 KB」硬断言。
//
//           ② **② 的封顶：p50 → p75**（`SCORING.teamPlanGapCapPct`）。
//              封顶值 = 池内差额的分位数，所以**池子一放宽，中位数自己就变小了**
//              （账号 1：11 → 9 金），② 的分辨率被压死：同一支补 4 金的队伍 ② 从 63.6
//              掉到 20.0，中段强队集体下沉。实测七种封顶规则后选 p75（= 14 金）：
//              强队回到前排（#1~#9），便宜队仍在 #7 / #10，**前 15 名的 ② 没有一支归零**
//              （p50 时是 50% 归零）。
//
//           实测（账号 1、默认权重）：最高分 **55.6 → 78.3**（第七轮修完是 75.2），
//           前 10 名的总分跨度 12.2 → **14.7**，且 #10 是那支补 2 金的白厄队。
//
//           回归：`team-plan-test.mjs` **24 项**全绿（新增两条 ⭐：「候选池取自逐档榜 ∪ 总榜」
//           —— 含三条回退用例；「真载荷上总榜池 ⊂ 逐档榜池」不变量）；
//           `CHECK_ADVICE_URL='http://127.0.0.1:8390/?view=advice' node tools/run-tests.mjs`
//           **17 个套件全绿**（含 CDP）。
//
//           ⚠️ 本节最该记住的一条教训：我一度把「总榜有 7 支队伍没进逐档榜池」当成真结论
//           写进了注释，实际是**我自己测试里的 `maxRows` bug** —— `options.maxRows` 只能
//           往下夹（`Math.min(SCORING.teamPlanMaxRows, …)`），两边都只拿到前 15 条，
//           于是拿两批 top-15 互比。后来写 `_probe-tier-superset.mjs` 才复核出真相
//           （0 支缺失）。**看到「缺失 N 条」先怀疑取样，再怀疑口径。**
//
//           新增探针：`_probe-pool-gate.mjs`（门外有多少便宜队）、`_probe-pool-tiers.mjs`
//           （每档池 × 总榜池对照）、`_probe-pool-all.mjs`（三池 + 全量）、
//           `_probe-pool-size.mjs`（三池体积）、`_probe-pool-compare.mjs`（A/B/C 并排 +
//           名次变化，两个账号）、`_probe-cap-rules.mjs`（B 池 × 七种封顶规则）、
//           `_probe-tier-members.mjs`（逐档榜带不带队友名单）、
//           `_probe-tier-superset.mjs`（逐档榜包不包含总榜）。
//
//   v4.6.83（**独立 worktree 分支 `fix/cap-basis`**，落在 v4.6.82 之上）：用户报
//           「我现在的前 10 是什么情况，怎么只有 50 多分」（附截图）。查出**两个**原因，
//           一个是真 bug：
//
//           ① **真 bug：刻度的取样集合错了。** 队伍抽卡方案的 ① / ② 两个百分位刻度在
//              v4.6.78 第五、六轮被改成取自「**要下发的那批**」。而用户第 5 条要求
//              「仅显示前 15 的补金建议」把 `teamPlanMaxRows` 从 40 改成 15 之后，
//              ② 的封顶值随之从 12 金缩到 **9 金** —— 同一条队伍「补 8 金」的 ②
//              从 33.3 掉到 **11.1**，最高分只剩 **55.6**。展示条数成了分数的隐藏输入。
//              修法：刻度改回取自**整个候选池**（p50 对离群值免疫，所以不会退回
//              「用 max 被 48 金的冷门队撑开」那个旧 bug），排序键直接就是总分，
//              截断 `ranked.slice(0, maxRows)` 变成**纯展示**。
//              实测（截图那套权重 + 隐金全勾）：封顶 9 → 12 金、②归 0 从 **9/15 → 0/15**、
//              最高分 **55.6 → 75.2**；且「展示 15 / 40 / 全池」三档的封顶值与每一条的
//              两个分项、总分**逐位相同**（三条不变量全过）。
//           ② **另一个原因不是 bug，是口径的数学结果**：① 与 ② 实测**负相关**
//              （`Pearson r = −0.250`：①≥80 的那支 ② 只有 11，②≥60 的那支 ① = 0），
//              加上「差额 0 金的队伍不进候选」（用户第 3 条）使 ② 的理论上界只有 88.9，
//              所以「补金推荐分」的**理论上界是 94.4，不是 100**。本轮**没有动它**
//              （要改就得动用户指定的等权口径，已在该 worktree 的文档里留作待拍板项）。
//           ③ **顺带查出的第二个真 bug：隐金减免的两处来源不同源。**
//              卡片「账面 N 金（含隐金减免 M 金）」那处传的是 `undefined`
//              （→ 模块级 `activeHiddenCostsState`），而补金顺序里**逐笔 cost** 传的是
//              `conclusion?.hiddenCosts`（→ HTTP 载荷）。界面只在用户勾选隐金窗口时才
//              `setHiddenCosts()`，**页面重新加载后它没有被初始化**（默认一项都不减），
//              于是浏览器里两者分叉：载荷带着 5 项全勾 → 逐笔 cost 算成 0 → 那几笔被
//              渲染层的 `filter(cost > 0)` 整批丢掉，补金顺序成空；而账面那行不写减免，
//              看起来像渲染丢了。实测那支队（Archer/银狼/花火/开拓者•记忆）：补金 2 金、
//              账面 7 金无标记、两笔（Archer E1 / 银狼 E1）都被逐笔 cost=0 丢掉。
//              修法：账面那处也传 `conclusion?.hiddenCosts`（该字段缺省时
//              `hiddenReductionOf` 仍退回模块级状态，工具侧行为不变）。
//              修后那支队变成「账面 1 金（含隐金减免 7 金）」——空列表因此有了正当理由。
//
//           回归：`team-plan-test.mjs` **22 项**全绿（新增两条 ⭐ 回归：①「展示条数不参与
//           任何计算」——用 `maxRows: 1 / 2` 与全量对比，断言刻度与每一条的分数逐位相同；
//           ②「隐金减免两处同源」——用真实英文键 `Luocha` 带得动减免，在「模块级状态 ×
//           载荷」四种组合下断言结果只由载荷决定）；
//           `CHECK_ADVICE_URL='http://127.0.0.1:8390/?view=advice' node tools/run-tests.mjs`
//           **17 个套件全绿**（含 CDP 那套，且是打在**本分支自己的服务**上的）。
//           `check-advice-layout.mjs` 一并修了三处被本轮换名次暴露的判据（表头文案、
