//               −2，但被**该项自己的金数**封顶（E0 本体 1 金、S1 光锥本体 1 金）；
//             * Archer E0 + 赠送光锥 S1（同一人）= **−2**（角色那份 1 + 光锥那份 1）；
//             * Archer E0 + 花火 E0 = **−2**（Archer 1 + 七人组那 1）—— 真实前沿池里
//               「整队减 2 金」的行绝大多数是这一形状（19+12+7+6… 次）。
//           * 穷举核验（全部 4230 条前沿行 × 逐成员，`tools/_probe-yinjin-archer.mjs`）：
//             角色那份 > 角色自付 **0 条**、光锥那份 > 光锥自付 **0 条**、
//             E0 Archer 的角色那份 > 1 **0 条**、S1 赠送光锥的光锥那份 > 1 **0 条**。
//           * 用户逐条确认**保持现状**（两问都选「各自独立」）：同一成员身上角色与光锥
//             各自封顶、**可以叠加**；七人组（自选其一）的 −1 与 Archer 那一笔**各自独立**。
//             这三条已写进 `herta-test.mjs` 的「特殊情况」用例并注明「用户拍过板」——
//             后续重构**别顺手合并**它们。
//           * 为此把 `hiddenReductionOf()` 的返回**拆成 `byIndexChar` / `byIndexCone`**：
//             合成一个数时只能「看起来没超」，拆开才能逐项穷举验证（界面不用这两个字段，
//             接口载荷形状不变）。
//           回归：`herta-test.mjs` **89 项全绿**（新增：E0 Archer 的角色那份 = 1、
//           S1 光锥的光锥那份 = 1、Archer + 赠送光锥 = 2、Archer + 七人组 = 2、三者叠加 = 3）。
//
//   v4.6.72 **表现列改成「直接写实测成绩」+ 表现曲线加精细梯度**（用户 2026-10-11
