//           要有更精细的表现权重变化梯度」）。两条都在上一轮 v4.6.69 的缺陷 3 之上。
//
//           ① **表现列只写实测成绩**（`perfLabelOf` → 新增 `metricShortText()`）：
//              改前是「档位写法 · 行动值」（`行动值 <300 · 285`），用户嫌啰嗦 ——
//              档位那半截在同一行的贡献链里已由系数体现，单位「行动值」上方脚注已说明。
//              现在：绝境 `285`、轮次制 `0T`、末日幻影 `3852`。
//              ⚠️ **顺带修掉一个隐蔽 bug**：末日幻影内部存的是 `av = 4000 − 积分`，
//              直接印会显示成 `148` —— 而它恰好落在「越小越强」的直觉里，错得很隐蔽。
//              `metricShortText()` 负责翻回积分。
//
//           ② **表现曲线改成全程严格递减**（`perfAnchorsOf()` 新锚点表 + `perfFactorOf()`
//              重写）：改前 `av ≤ 满分线` 整段是**平的 1.00**，于是绝境里行动值 37 与
//              299 拿同一个分（frontier 池 perfect 档实测跨 [37, 299]），**档内零区分度**
//              —— 这正是用户说的「要更精细的梯度」。
//              现在以 `av = 0` 为顶点，依次穿过三条判据线，段间线性插值：
//                `0 → 1.00 → 满分线 0.85 → 达标线 0.50 → 及格线 0.25 → 线外衰减到 0.05`
//              设计取舍：**达标线仍取 0.50**（与旧 `frontierTierWeight` 一致，「跨过
//              达标线」这个分界没被动）；**满分线取 0.85** 是给满分档留梯度的代价，
//              跨档落差（0.35）仍远大于档内落差（0.15），原设计意图保住。
//              满分线 = 0 的副本（混沌 / 虚构 / 末日幻影）与顶点重合 → **跳过该锚点**，
//              曲线直接从 1.00 接达标线。
//              ⚠️ 踩过的坑：线外外推曾写成 `yn - (yn - yp) × …`，两个负号相消后
//              **反向上升**（实测 av=800 → 1.025）。已加全程单调性回归用例拦它。
//
//           ③ 脚注改成「列里是实测成绩，系数按 <档位 系数对>」；曲线说明按锚点现算，
//              **档位名按锚点 av 值反查**（不能用「第 i 个锚点 = 第 i 个档位」——
//              跳过满分锚点时会整体错位，实测写成过 `0T 1.00 → 0T 0.50`）。
//              总长压到 58 字（脚注有 60 字硬上限）。
//
//           回归：`herta-test.mjs` 86 → **88 项**（新增「表现曲线：全程严格递减、锚点
//           落在三条判据线上」，含单调性抽样 + `metricShortText` 末日幻影翻值）；
//           `e2e-test.mjs` 120/0；CDP 套件表现列与脚注断言同步（表现列正则改成
//           「裸数字或 `N T`」）。
//
//   v4.6.71 **「隐金设置」详情页加一条备注，把「特殊情况」提示出来**（用户 2026-10-11
//           同一轮追加原话：「你要加个备注，提示用户特殊情况」）。**纯显示层**，
