//
//   v4.6.70 **新增「隐金设置」—— 总榜权重下方的按钮 + 详情窗口，把这些不用抽就有的
//           角色 / 光锥的成本从性价比总榜里去掉**（用户 2026-10-11 第 9 轮原话：
//           「在性价比总榜添加一个按钮，用于额外设置，将其放置于总榜权重下方……
//            点击后弹出详情界面，角色和光锥都需要有图标，详情页要美观可用，
//            界面信息不出界，以下复选框默认已点击」）。五组复选框，**默认全勾**：
//
//             ① 直接受赠角色（真理医生 / Archer / 丹恒•腾荒 / 吉尔伽美什 /
//                景元·卡芙卡·丹恒•饮月·镜流·花火·黄泉·砂金）→ 该角色少 1 金（最低 0）
//             ② 累计抽卡赠送光锥（理想燃烧的地狱 / 所见即我）→ 该光锥少 1 金（最低 0）
//             ③ 角色兑换（罗刹 / 阮•梅 / 托帕&账账 / 藿藿 / 知更鸟）→ 角色**及其星魂** 0 金
//             ④ 光锥兑换（于夜色中 / 棺的回响 / …共 11 把）→ 光锥**及其叠影** 0 金
//             ⑤ 后续加入的常驻角色（希儿 / 云璃 / 银枝 / 银狼 / 符玄 / 刃）→ **及其星魂** 0 金
//
//           ① **作用面是「队伍金数」**（用户 2026-10-11 明确选择「会改排名」那一条）：
//              总榜的分母是「该配置的队伍金数」，所以减金真的会改名次，而不只是改显示。
//              逐版本最便宜金数（分子）与榜上印的 `N 金` 都跟着一起减 —— 否则会出现
//              「分子按原价、分母按隐金后」的错配。抽卡方案 / 差距榜 / 星魂榜**不受影响**。
//           ② **减到 0 金的整包仍然留在榜上**（用户明确选择）：进榜判据仍用**原始**金数
//              （「0 金配置没有可比性」这条旧规则不变），只是榜上印 0 —— 不然「角色兑换 /
//              常驻角色」那两组一勾选就整批从榜上消失，等于看不见效果。
//           ③ 用户给的「特殊情况」逐条实现（**不显示在界面上**）：Archer 单独 -2、
//              与吉尔伽美什同队各自 -1；七人组是**自选其一** → 一队里出现几个都只减 1；
//              光锥同理（单独的理想燃烧的地狱 -2）。
//           ④ **两套金数口径**（实测逼出来的）：数据集那条 `c` = 本体 + **真实**星魂级数 +
//              光锥本体 × 叠影（实测 4230/4230 行完全一致），而 `packGoldOf` 用的是
//              **目标档**星魂、且不算叠影。所以「该配置金数」按前者减、「榜上印的 N 金」
//              按后者减；把某单位「视为 0 成本」时按它所在的那个数减，否则留 1 金残渣。
//              另外角色那一份与光锥那一份**各自夹逼**（各按自己的成本封顶）—— 合成一个
//              累加器时，一把 S1 的赠送光锥会把角色本体的 1 金也减掉（实测踩过）。
//           ⑤ 整队都被减到 0 时按 **1 金**计（`max(1, stored - cut)`）：分母为 0 会算出
//              Infinity，分子一旦为 0 又会把所有人的金数项一起打成 0。
//           ⑥ 接口：`POST /api/archive/conclusion` 收 `hiddenCosts`（五个布尔），
//              响应回显归一化后的那一份，载荷形状 → **payload: 5**；
//              `GET /api/archive/packs` 走查询串 `?hiddenCosts=…`（面板与榜面必须同口径，
//              与 v4.6.69 修的权重不一致是同一类 bug），形状 → **payload: 2**。
//              ⚠️ **不传 = 一项都不减**（工具 / 老调用方 / 回归测试的历史口径不变）；
//              「默认全勾」只是**界面**的默认值（localStorage 没有存档时）。
//           ⑦ 界面：`public/index.html` 在 `#adviceFrontierWeights` 之后加
//              `#adviceHiddenCostsBar`（按钮 + 状态行）；`advice-gold-modal.js` 是窗口
//              外壳（懒建、三条关闭路径、"恢复默认"）；正文由 `advice-view.js` 现建
//              （三组加粗标题 + 五个复选框 + 单位图标 + 「效果：…」）；存档进
//              `hsr.advice.hiddenCosts`，改动**立即生效**（防抖后重算总榜，并清
//              `packsCache`）。
//           实测（本机当前数据集，4230 条前沿行）：**1422 行（33.6%）**的队伍金数被减、
//           共减 2526 金、其中 104 行被减到 0（走 1 金兜底）；榜面条数不变（62 条，每个
//           角色仍只出一条）。点名单位名次变化举例：花火 #6→#2、吉尔伽美什 #17→#9、
//           银狼 #41→#25、知更鸟 #47→#35；罗刹 / 真理医生 / 云璃 / 景元 / 镜流在当前
//           前沿池里本来就没有配置，**不受影响**（功能只对榜上真出现的单位有效果）。
//           回归：`herta-test.mjs` **87 项**（82 → 87：五组规则逐条夹具 + 真实数据集
//           上「总榜真的变了、方案一字不变」）；`e2e-test.mjs` 新增接口回显与
//           「面板最高分配装 = 榜上那一条」；`check-advice-layout.mjs` 新增按钮位置、
//           窗口四边不出界、五个复选框默认全勾、35 张图标真的加载、勾选后榜面重算
//           与三条关闭路径。探针：`tools/_probe-yinjin-impact.mjs`（效果 + 名单核对）、
//           `tools/_probe-yinjin-cost-formula.mjs`（`c` 的口径证据）。
//
