//   v4.6.66 **性价比详情里那一栏「版本」改名叫「跨版本发挥」**（用户 2026-10-10 第 6 轮：
//           「这个版本太抽象了，叫什么名字比较合适」）。**评分口径一字未改**，纯显示层。
//           ① 那一栏（`frontierFactorsOf().seasonFactor`）与左边的版本权重表**同名但不同义**：
//              权重表是 2:2:2:1:1:1:1 的固定系数（对所有人都一样），而这一栏是
//              **余数** —— `评分 ÷ (100 × 档位 × 行动值 × 金数)`，即「各版本加权平均
//              ÷ 最好的那一版」，恒 ≤ 1。用户在截图里看到的 `×0.49 / ×0.64 / ×0.37`
//              就是它，叫「版本」既看不出在算什么、又和权重混在一起。
//           ② 全榜 177 条明细的分布（改名时实测）：中位 0.416、只有 2 条（1%）能到
