//              （「跨版本发挥 = 各版本加权平均 ÷ 最好的那一版 —— 越接近 ×1 说明各版本都稳。」），
//              因为改名本身解决不了「看不懂」，得把算式摆出来。
//           ④ 同步 `tools/check-advice-layout.mjs`：`SOURCE_HEADERS` 第 6 项与
