//           67/67 合格。回归：`check-advice-layout.mjs` 的「总榜行图标」那一组新增
//           「图标在花费格里、在光锥文字右边」两条几何判据（`coneOutside` /
//           `coneLeftOfText` 必须为 0），只在 DOM 顺序或实际像素任一处不满足都算红。
//
//   v4.6.63 **金数项按版本归一**（用户 2026-10-10 第 5 轮：「4.2 那期才有可能打满
//           （最容易压金的版本），是不是对别的版本不利？」）。
//           ① 是的，而且实测比预想更普遍：24 个「副本×版本」组合里 **18 个吃亏**，
//              且吃亏的恰好是**权重 2 分的最新版**（pf 4.5 的 −66.7%、moc/as 4.5 的
//              −50%、绝境 4.6 的 −12.5%）。根因：金数项的分母 `minCost` 取的是
//              **整个窗口**的最小值（= 历史上压金最狠的那一期），于是其余每一期都被
//              按那一期打折 —— 罚的是**环境难度**（怪物配置本身难压金），不是队伍优劣。
//              绝境实测各版本最便宜：4.0→10 / 4.1→11 / 4.2→7 / 4.3→10 / 4.4→7
//              / 4.5→9 / 4.6→8，而全局 minCost = 7（来自 4.2 与 4.4）。
//           ② 改成 **「该版本最便宜 ÷ 本队金数」**，再按版本权重加权。这样每个版本
//              内部公平比较（同在 4.1 那期，11 金就是最省），环境难度不再惩罚队伍。
//              跨副本的「绝对金数不可比」不受影响 —— 归一化仍在**副本内**做，
//              所以「绝境 10、其余 1」那张副本权重表照旧成立。
//           ③ 连带：`minCost` 降级为**展示/兜底**（不再进算分），新增
//              `minCostBySeason`（副本元数据）与 `unit.envs[].seasonMinCost`（逐条）下发；
//              `frontierFactorsOf` 优先读后者，否则浮层里的金数项会与榜上的分对不上。
//              ⚠️ 这里有个容易漏的坑：`seasonMinCost` 要穿过**三道**映射才到界面
//              （`pack.evidence` → `unit.envs[]` → 返回的 `frontierEnvs`），
//              少写一处就静默变 null（实测：用例报 `null !== 4`，浮层退回旧口径）。
//           实测（67 条）：真珠 E2 **700 → 800**（绝境金数项 0.700 → 0.800，因为
//           4.6 那期环境更贵，8 金已是该期最省）；榜首仍是真珠，第 2~5 名微调。
//           不变量「权重 × 分 = 贡献」0 违例；版本因子仍恒 ≤ 1。
//           回归：`herta-test.mjs` 79 → **80 项**。新增「金数项的分母是本版本最便宜」，
//           断言「本版本内最省的队伍拿满 1.000」（旧口径会算出 0.500，一眼可辨），
//           并断言 `minCostBySeason` 真的下发。另修两条夹具：它们原先把
//           「版本间金数水位一致」当成默认前提，新口径下得显式守住。
//           另修 `_probe-version-factor.mjs`（它独立重算金数项，不改会打「✗ 不一致」）。
//           ⚠️ 服务端改动的生效条件：`src/**` 必须**重启** `bin/serve.mjs`。
//
//   v4.6.62 **登场版本改为「按副本取」**（修一个线上 bug，用户 2026-10-10 问
//           「为什么真珠目前的版本权重才 0.5」）。
//           0.5 不是版本权重表的值（那张表只有 2 和 1），是**版本因子**那一栏的显示：
//           真珠在绝境 140 ÷ 4 = 35，除以最佳证据版 70 → ×0.50。分母里多出来的那个 2，
//           来自「4.5 算 0 分（已登场无人使用）」—— 而那个判定是错的。
//           ① 根因：黑塔网**四个副本各用一套版本号**，同「一期」真实日期在不同副本里编号
//              不同。用投稿的 `video_date` 对齐实测：2026-09-28~10-04 那一期在
//              异相仲裁叫 **4.6**、混沌回忆叫 **4.5**、末日幻影 4.6、虚构叙事 4.5。
//              旧实现只存一份**跨副本取最小值**的全局 `firstSeen`，拿它去比每个副本的
//              窗口 → 判定错位。真珠在异相仲裁的登场版本是 4.6，全局值却是 4.5
//              （混沌那边编号更小），于是 4.5 被判「已登场却无人使用」算 0 分 ——
//              而那一期真实日期（2026-08-26）比真珠首次出现早一个月。
//           后果：版本因子被压到 ×0.50、总分 700 → 350、榜首让给别人。
//           ② 修法：`herta-build.mjs` 除全局值外**再存一份 `refs.firstSeen.byMode`**
//              （`模式全名 -> {characters, lightCones}`，按各副本自己的编号算）；
//              评分侧优先读本副本的值，全局值只在老数据集没有 `byMode` 时兜底。
//              ⚠️ 键要用模式**全名**（`Anomaly Arbitration`）—— `env.mode` 给的是短码
//              `aa`，必须过 `MODE_ALIASES` 翻一次。第一版修完没翻别名，全部静默落回
//              全局值，表现为「改了但没生效」，这一点也写进了回归用例。
//           ③ **需要重建数据集**（`node tools/herta-build.mjs`）`byMode` 才存在 ——
//              它只改 `refs`，不动投稿结构。
//           实测（67 条，条数不变）：真珠回到榜首（350 → **700**，版本因子 ×0.50 → ×1.00）；
//           「无人使用」判定从 653 降到 **453**（那 200 个多半就是版本号错位造成的冤枉），
//           「不参与」从 101 变成 106，有观测 492 → 666。
//           回归：`herta-test.mjs` 78 → **79 项**。新增「登场版本必须按副本取」，
//           用**同一个整包跑两遍**（只有全局值 vs 带 byMode）钉死差异：
//           误判时 50 分、按副本取时 100 分，并断言后者必须更高。
//           ⚠️ 服务端改动的生效条件：`src/**` 必须**重启** `bin/serve.mjs`。
//
//   v4.6.60 **早于登场的版本改为「不参与平均」**（废除「按场地水平放大」，用户
//           2026-10-10 追问「为什么有的角色的版本权重超过了 1，这合理吗」）。
//           用户判断：不合理。根因是 v4.6.47~v4.6.56 的「早于登场 → 按场地水平等比例
//           放大（上限 ×2）」—— 放大出来的推算分会**反超实测分**，于是「版本因子」余数
//           大于 1。实测榜首真珠 E2：唯一实测的那版（4.6）只贡献 140/910 = **15.4%**，
//           其余全是它 4.5 才登场、却在 4.0~4.4（当时根本不存在的版本）按 ×2 推出来的。
//           ① 现在版本维度是**三态**，语义各不相同：
//                有证据             → 实测分
//                缺证据 且 早于登场   → **不参与平均**（不进分子也不进分母）—— 无从判断
//                缺证据 且 已登场     → **算 0 分**（进分母、不进分子）—— 明确的差
//              用户第 6 条的本意是「不罚新角色」，而 **不参与 ≠ 罚**：既保住第 6 条的
//              意图，又不编造一个当时不存在的成绩。
//           ② 连带删掉整套放大机器：`SCORING.creepAmpMax`、场地水平中位数 `levelOf`、
//              `refLevel`，以及 `estimatedSeasons` / `amplifiedSeasons` 两个字段 ——
//              它们只服务放大，现在没有消费者。取而代之的是 `absentSeasons`。
//           ③ 新字段 `absentSeasons`（逐副本 + 整包合计）随载荷下发。⚠️ 它与
//              `droppedSeasons` **含义相反**（一个「无从判断」、一个「明确的差」），
//              界面分两句报：「N 个版本整包还没登场，不计入」/「N 个版本已登场却无人
//              使用，算 0 分」。
//           ④ 「版本因子」不再可能 > 1（实测 179 条明细里只剩 1 条 2e-6 的浮点噪声），
//              它重新是一个**纯折扣**。
//           实测（67 条）：榜首换人 —— 真珠 E2 910 → **350**（跌出前 10），
//           新榜首 不死途 E0 **535**。这是因为放大被废除后，只有真正有观测的版本算数。
//           回归：`herta-test.mjs` **78 项**全绿。删掉「按场地水平等比例放大（第 6 条）」
//           与「只有早于登场的旧版本才放大（v4.6.47 修复）」两条旧用例（口径已废），
//           换成「早于登场不参与平均（且不奖不罚、不得反超实测）」「不参与时分母只含
//           参与的版本」「已登场却无人使用算 0 分」三条。
//           `tools/_probe-version-factor.mjs` 同步改成三态（它独立重算，规则不改会
