//           浮层里装着 v4.6.57 那一节「该角色的全部配装」，那一节**限高滚动**，所以
//           指针必须能留在浮层里 —— 下面每一条都是「一碰就关 / 滚不动」的一个必要条件：
//           ① 显隐从纯 CSS 的 `:hover` / `:focus-within` 改成 JS 的 `.is-open`
//              （`wireValueTips()`）。hover 显隐下，指针从徽标往浮层挪的**那条路上**
//              就会 `mouseout` → 浮层当场收起。同理**删掉** `container` 上的 `scroll`
//              收起监听：页面滚动时固定定位的浮层自己跟着视口走，收起它才是 bug。
//           ② 浮层 `pointer-events: none → auto`：否则指针进不去、清单的滚动条拖不动。
//           ③ ⚠️ **点在浮层里面不算「点徽标」**。浮层 DOM 上是 `.advice-value-wrap` 的
//              后代，只判 `closest('.advice-value-wrap')` 的话，「在清单里按一下 / 拖一下
//              滚动条 / 选一段文字」都会被当成「再点一次徽标」而把它收掉（滚轮能滚、
//              一碰就关 —— 用户看到的还是「滚不动」）。判据顺序必须是**先判浮层、
//              再判徽标**。这一条是本轮真正修掉的那半个 bug。
//           ④ 收起的监听从**容器**挪到 **document**：浮层是固定定位的，可以飘到容器
