//   v4.6.78 **绝境王棋关的表现曲线按副本覆盖：满分线以内固定 1.00、达标线 0.60**
//           （用户 2026-10-11 第四轮原话：「绝境王棋关的表现权重需要更新，行动值小于
//           300，权重固定为 1.00；行动值 300-500，权重在 1-0.6 之间逐渐变化」）。
//           只改一个副本的一条曲线，但它是总榜权重最高的副本（×10）。
//
//           ① 改法：v26 那三个判据线取值（0.85 / 0.50 / 0.25）是**所有副本共用**的
//              默认值，本轮新增 `SCORING.frontierPerfLineByEnv`（键与 `SCORING.envWeight`
//              同一形状 `${站点全名}|${关卡}`），绝境覆盖两档：
//                  'Anomaly Arbitration|plight': { perfect: 1, target: 0.6 }
//              取值由**唯一一个** `perfLineWeightsOf(env)` 解析（短码 / 全名 /
//              `aa|plight` 与 `aa/plight` 两种 id 写法都认），四处调用点全部改走它：
//              算分（`buildConclusionInner`）、浮层拆因子（`frontierFactorsOf`）、
//              服务端「未进池投稿」质量估算（`archive.js` 的 `observedPackScores`）、
//              界面脚注（`advice-view.js` 的 `perfCurveText`）。`perfAnchorsOf()` /
//              `perfFactorOf()` 各多一个可选的 `weights` 入参（不传 = 默认那套）。
//              ⚠️ **为什么不直接改那三个常量**：它们服务另外四个副本，动一下会连带改掉
//              混沌 / 虚构 / 末日幻影 / 骑士关的曲线。按副本覆盖之后，以后要给别的副本
//              另一套（v28 第 4 条提过的末日幻影单独 perfect 线）只需往表里加一行。
//
//           ② 新曲线（绝境判据线 满分 300 / 达标 500，无及格线），锚点 `[[0,1],[300,1],[500,0.6]]`：
//                  av < 300        → 1.00（**平的**：满分线以内不再有 1.00→0.85 的缓降）
//                  300 ≤ av ≤ 500  → 1.00 线性降到 0.60
//                  av > 500        → 沿最后一段斜率继续衰减到地板 0.05（实测 av=775 触底）
//              ⚠️ 「37 与 299 同分」是**本轮需求**（v26 曾为要梯度把这一段改成缓降），
//              曲线因此只保证**单调不增**；`herta-test` 的单调性抽样同步改成「不增 + 不越界」。
//
//           ③ 实测（`tools/_probe-perf-plight.mjs`，只读；同一份数据、同一段代码，只切那张表
//              跑两遍。⚠️ 「改动前」必须**连前沿一起重取** —— `archiveFrontier` 取前沿时就把
//              `observedPackScores` 按当时曲线算好了，只清空开关会让「改动前」在**有未进池
//              证据**的条目上高出几分，量出来的差值就混进了无关因素）：
//                  · 绝境前沿池 433 行：表现因子平均 **0.6991 → 0.8201（+17.3%）**，贴地板 0 行
//                    （`0.6991` 与 v28 留档逐位一致 —— 复算的就是生产那条链）；
//                  · 榜面条目：绝境 **29/29 条**分值变、平均 47.59 → 55.64；其余四个副本
//                    **0/30、0/22、0/39、0/42 条**变化，平均分逐位不变；
//                  · 榜面前 15（前 → 后）：不死途 993→1105、千冶•刃 957→1074、真珠 854→1000、
//                    砂金•戏浪 813→950(#5→#4)、爻光 820→936(#4→#5)、缇宝 788→888、
//                    姬子•启行 769→861、花火 724→826、长夜月 715→812(#10→#9)、
//                    昔涟 719→809(#9→#10)、银狼LV.999 699→807(#12→#11)、风堇 686→806(#13→#12)、
//                    知更鸟•晴歌 682→800(#14→#13)、开拓者•记忆 707→793(#11→#14)、火花 646→747。
//                    榜首顺序不变、最大移动 3 位 —— 这是**权重最高副本的整体抬升**，不是重排。
//
//           ④ 回归：`herta-test.mjs` **92 项全绿**（改前 91 passed / 1 failed）。两条用例改写：
//              「表现曲线」新增绝境逐点断言（37/299/300 → 1.00、400 → 0.80、500 → 0.60、
//              700 → 0.20、775 → 地板）+ **默认套不受影响**（300 → 0.85、500 → 0.50 仍钉着）
//              + `perfLineWeightsOf` 的键归一（短码 / 全名 / 两种分隔符 / 骑士关与末日幻影
//              不沾光）；「贡献值来源」期望值按新曲线重算（`perfFactor` 0.925 → **1.00**、
//              `seasonFactor` 0.946396 → **0.976667**）并**直接钉住该副本的分 = 65.1111**
//              —— 只改函数、忘了给调用点传权重时这条会红。`e2e-test.mjs` **124/0**。
//              v28 那支探针（`_probe-perf-audit.mjs`）**同步传 `perfLineWeightsOf(env)`**：
//              它以前直接读常量，不改就会打印旧曲线、看起来却像程序的行为。
//              ⚠️ CDP 布局套件（`check-advice-layout.mjs`）本轮没跑（需要 9222 上的调试
//              浏览器）；它那条脚注正则不写死数字，但界面上绝境那三格的实际文案
//              （`行动值 0 1.00 → <300 1.00 → <500 0.60`）**未在浏览器里验证过**。
