//           链路（三个环节缺一不可，所以一直没被发现）：
//             ① 逐档榜的整包只随结论载荷下发 **1 个 env**（`slimFrontierUnit(unit, i, 1)`），
//                而 `envCount` 写着真实条数；
//             ② 界面开浮层时 `enrichTierDetail()` 会用 `/api/archive/packs` 的数据
//                **整份替换 `unit.envs`** 再重画因子表；
