//             * `check-advice-layout` 在**逐档榜浮层补齐明细之后**量第 5 列，每一格必须 ≤ 1。
//           修后同一批 305 行只剩 10 行 > 1，且超出量 ≤ 8e-6 —— 那是载荷把 `score`
//           四舍五入到 4 位小数造成的（界面显示仍是 ×1.00），不是口径。
//
//           教训：**同一个数字被两条投影分别供给时，两份投影必须在「界面要现算的字段」上
//           等价** —— 少一个字段不会报错，只会静默算出一个不可能的数。
