//           `goldPct`、计划的 `goldMax` / `goldCapPct` / `costMix`）。现在的等式是
//             `补金推荐分 = 强度得分 × 强度权重 + 性价比 × 性价比权重`
//           界面上不再出现「性价比得分」这个名字（同一个数套两个名字正是用户说的「重叠」），
//           详情窗口的「分数来源」表从 4 行缩到 **2 行**（强度得分 / 性价比）。
//           「账面 N 金」仍在每张卡明面上显示，只是**不进分数**。
