//           连带要记住的一件事（别把它当成回归）：那支被点名「过时」的 16 金队伍从 #8 回到
//           **#2**。它不再是 #1，靠的是同轮的**版本窗口 7 → 3 版**（纯强度 1390.8 → 1378.5），
//           而不是金数刻度 —— 也就是说本轮之后**它不会再因为「总共 16 金」被扣分**。
//           想让「总共几金」重新进公式就必须加回第二个金数刻度，那正是用户这次否掉的方案；
//           实测（账号 1，默认权重）它是 #2 / 85.1 分，第 1 名是同样补 4 金、账面 11 金的那支。
//           复算：`node tools/_probe-team-plan.mjs --account=1 --rows=8`。
