//           根因两半：① **刻度的下限取的是「池内最弱的那支队」**（实测 16.7，那是一支
//           1 金血分队），而争冠队伍都在 1330~1397 —— 只占全量程的 **4.8%**，于是任何有
//           竞争力的队伍算出来必然 95~100（池内 220 支里 14 支 ≥95）；② 「表现」那条曲线在
//           绝境（权重 ×10）**行动值 < 300 时固定 1.00**（用户 2026-10-11 自己定的），
//           前 10 张卡里 8 支的绝境行动值都在 286~298 ⇒ 它们在权重最大的副本上拿的是同一个
//           表现分，raw 强度只差 1.3%。（只有行动值越过 300 的那两支算出 74 / 78 分。）
//
//           改法：① 的下限改成**池内分位**（`SCORING.teamPlanStrengthFloorPct = 0.75`，
//           与 ② 的 p75 封顶对称：一边「超过就没分」、一边「低于就没分」），上限仍是最大值。
//           实测（账号 1，池内 p75 = 891）前 15 名的强度得分跨度 **26 → 71 分**，
//           前 8 名从「清一色 95+」变成 87~100；补金 3 金但行动值 404 的那支掉出前 8。
//
//           ⚠️ 用户同时提了一句「强度和成本息息相关」，实测**只在成本内部成立**：
//             * 池内 `r(纯强度, 账面金数) = 0.24`、**头部（强度 ≥ 1300）是 −0.65**
//               （越便宜反而越强 —— 金数不进强度，9 金的满分与 24 金的满分拿同一个表现分；
//               实测 9 金那支强度 1390 > 16 金那支 1378 > 40 金那支 1267）；
//             * 真正高度相关的是 **`r(账面金数, 补金差额) = 0.95`** —— 对这个账号，
//               「这支队总共几金」与「你还要补几金」几乎是同一个数。这正是 v4.6.89 删掉
//               「压金度」的数据依据（成本的两个面已经合成一个），删对了。
//           所以这次抬下限**不是**把成本偷偷带进强度那一档，恰恰相反：它让「便宜还能满分」
//           的队伍更占优，与用户「已被更能压成本的队伍取代」的诉求同向。
//           复算：`node tools/_probe-strength-scale.mjs --account=1`（分布 / 四种锚点 / 相关系数）。
//
//   v4.6.91 用户 2026-10-12 第 8 条：「回退此改动，就抽卡方案提供的强度而言，同样是绝境 0T，
