//           一句话：**① 必须含金数项**，所以 v4.6.87（纯强度）与 v4.6.90（分位下限）**两条一起撤销**。
//
//             * ① 回到 `unit.total` = Σ_副本 副本权重 × (100 × 表现 × 金数项)，
