//               于是「同为绝境 0T，9 金那支 1039 分 vs 16 金那支 724 分」——差 1.4 倍，
//               这正是用户要的那条区分线（实测账号 1：9 金那支 ①=88.3，16 金那支 ①=61.4）。
//             * 删除 `packStrengthOf()`、整包的 `strength`、逐副本的 `strength`
