//           ① **顶栏头像的背景改成无色**（用户原话「网页左上角的头像的背景颜色改为无色」）：
//              去掉那层金色渐变底与围着它的金色光晕（那圈光在透明底上就是一圈有色的底），
//              悬停反馈改成「轻微上抬 + 提亮」。跟着一起改的是 `.brand-mark-glyph` 的颜色
