//              `.modal-card`，而那个类**没有 `max-height`** —— 88 个头像把卡片撑得比视口还高，
//              `.modal` 又是 `place-items: center` 的居中网格，上下溢出部分被切掉且滚不动。
//              现在按仓库高浮层的既有做法（`.advice-gold-card`）：卡片 `max-height` + flex
//              纵列 + `overflow: hidden`，正文 `min-height: 0` + `overflow-y: auto`，
