//              实测 DOM **26,561** 个节点里 **21,339（80%）** 都在这 92 个浮层里、803 张图里
//              400 张也在里面，而同一时刻**只会打开一个**。现在渲染时只放一个空占位
//              （`lazyTip()`），第一次点开才建内容：节点降到 **5,222**、图片 403、
