//              请求，实测两个页面都只拉 1 次。
//
//   v4.6.101 用户 2026-10-14 把「强度」这一项的口径**从头重定**，本轮落地并顺手查出三个真漏洞：
//           ① **强度改成围绕行动值**（用户三段原话：「强度分应当围绕行动值决定…**仅取最少
//              行动值**」「按照已有的用户设置的关卡权重**各自贡献**」「任何角色的只考虑强度
//              权重都必须是 **E6S5 > E6S1 > E2S1 > E0S0**，哪怕 E6S1 就能达到 0 行动值
//              （从而压金），E6S5 的此角色的强度仍然必须在 E6S1 之上」）。落地：
//              `强度分 = 95 × 单调包络的行动值表现 + 5 × 投入档位` ——
//              每个副本取该整包**最少行动值**那一次成绩（不跨版本平均），按用户设的关卡
//              权重加权平均；再按「星魂 ≤、叠影 ≤ 的档位里打过的最好成绩」**向上兜底**
//              （多一叠影只会更强，不该被稀疏投稿冤枉）；最后 5 分按
//              `(星魂档 + 叠影档) / 11` 给，保证行动值饱和（都 0 行动值通关）时这条链
//              仍然**严格**递增（实测风堇 95.5 → 98.2 → 100.0）。
//              强度分现在是**绝对刻度 0~100**，不再榜内 min-max（性价比 / 泛用性仍然归一）。
//           ② **修一个反向激励**（上一版引入的）：强度除以「**有数据的**副本」→ 投稿副本越少
//              分越高（只要一个混沌 0T 就是满分），总榜「每角色留一条」于是专挑数据最少的
//              整包 —— 实测**绝境覆盖率从 36/77 掉到 1/77**，而绝境正是唯一按行动值判、
//              权重 5 的那一项。改回除以**全部**副本的权重（缺副本按 0 计，与仓库既有口径
//              「已登场却没有任何成绩 = 算 0 分」一致）：覆盖率回到 **56/77**，总榜中位从
//              96.5 回到 **74.9**、≥90 的占比从 97% 回到 **30%**、最高分不再并列。
//           ③ **成本账：光锥叠影要算钱**（用户点名「E6S5 的限定角色+限定光锥**不算隐金**
//              应当是 **12** 成本」）：`packGoldOf` 改前只算光锥本体 → S1 与 S5 同价、
//              E6S1 与 E6S5 都印 8 金。现在 = 本体 1 + 星魂 6 + 光锥本体 1 + 叠影 4 = **12**。
//              连带修 `hiddenReductionOf` 的「整包展示口径」（它也没算叠影 → 隐金只免掉
//              光锥本体那 1 金、剩下的叠影钱留在榜上，实测本该减到 0 的整包仍显示 4 金）。
//           ④ **强度来源表按新口径重做**：列改成「关卡 / 最少行动值 / 本副本强度 / 权重 /
//              贡献」，并写出「本档自身合计 → 单调兜底 → 投入加成 → 强度分」这条链 ——
//              不写出来的话读者会拿两档的**原始合计**去比（稀疏投稿时确实会 S1 < S0），
//              看着像算错了。顺带修好「权重」列**恒印 ×0**（服务端从来没投影过 `env.weight`）。
//           ⑤ **新增回归**：`tools/strength-invariant-test.mjs`（成本账 7 条 + 抽样 8 个角色
//              共 **638 组可比档位**的投入单调性 + 点名那条链的严格递增），已接进套件清单。
//              它当场抓到一个洞：最初用「整包金数」算投入，而 4★ 光锥叠影不算钱 → 出现
//              `E2S1(95.8) > E2S5(95.4)`；改成纯按 (星魂, 叠影) 档位后包络与投入项同尺。
//
//   v4.6.102 用户接着报的第 4 个漏洞：「从纯粹强度考虑，**1+1 爻光为什么不如 1+0 爻光**」。
//            查证：爻光 E1 档上，`菇菇嘎嘎历险记 S5`（**免费锥**，整包 2 金）强度 **95.0**，
//            反而高于 `当她决定看见 S1`（**专武**，整包 3 金）的 **93.2** —— 原因是我在
//            v4.6.101 里把「投入档位」写成了 `星魂档 + **叠影次数**`，于是**免费 / 4★ 光锥的
//            S5 也被算成 5 档投入**，一分钱没多花却拿走 5/11 的投入分。用户给的成本口径是
//            「E6S5 的**限定**角色 + **限定**光锥不算隐金应当是 12」——**投入按金算，不按叠影
//            次数算**。两处一起改：① `coneRankOf()` 只认**要金的光锥**（`coneCostOf() > 0`）
//            的叠影；② 单调包络要求**至少一维严格更低**才兜底（档位相同时不互相兜底，
//            否则「不装光锥」会白捡「装了免费锥」的成绩 —— 免费锥是实打实的提升，只是不花钱）。
//            修后爻光：E1+专武S1 = **93.2** > E1+免费锥S5 = **86.3** > E1 无光锥 = **85.4**，
//            且整条链仍严格递增（E2+专武S1 94.2 → E6+专武S1 96.8 → E6+专武S5 100.0）。
//            回归：`tools/strength-invariant-test.mjs` 换成与实现**同一把尺子**（星魂档 +
//            要金光锥的叠影档），新增「要金锥必须压过免费锥」这条断言，可比档位从 638 组增到
//            **766 组**；`herta-test.mjs` 两条跟着新口径。
//
//   v4.6.103 用户 2026-10-15 报：「查下这个程序，为什么此配队的强度得分拿了 100 分，不应该还有
//            成本更高的队伍吗？」—— 查证结果：**抽卡方案的 ① 没有跟着 2026-10-14 第 10 条换口径**，
//            它还在读**老口径的整包分**（`unit.total`，含金数项）并**按候选池 min-max 归一**，
//            于是池内**最省金**的那支必然拿 100 分，而「成本更高、行动值更低」的强队反而更低
//            （用户截图那张卡：账面 10 金 / 补金 8 金、强度 100.0，而同池里绝对强度更高的那几支
//            落在 #8 / #13 / #14）。**同一个词在两个榜上指了两个东西** —— 这正是它被发现的路径。
//           ① **抽卡方案的 ① 现在与角色总榜那一列同一个数**：
//              `strengthPct` = 该队**成员整包**在总榜上的 `strengthScore` 里最高的那一个，
//              **绝对刻度 0~100**（`plan.strengthLo / strengthHi` 变成常量 `0 / 100`，
//              不再按候选池现算）。取「成员最高」而不是「头条整包自己」：`strengthScore` 是整包
//              自己的属性，头条只是**恰好**由某个成员带头 —— 实测两者能差 5 分（89.0 → 94.0）。
//           ② **实测（本机真账号，`node tools/_probe-strength-100.mjs --account=1`）**：
//              修前 ① = 池内 min-max(整包分)：池内第一拿 **100.0**（账面 11 金那支），
//              而绝对强度更高的 13 金 / 15 金那几支只拿到 63 / 61。
//              修后 ① = 绝对强度分：同一账号池内 **242 个整包**的分布是
//              `min 6.1 / p25 30.3 / p50 52.8 / p75 89.1 / max 98.7` —— 分辨率**更好**，
//              而且 100 分只留给「行动值拉满 + 投入拉满」的整包（修前是「谁最省金谁满分」）。
//              默认 1:1:1 权重下那一档的榜首仍是补 6 金的队（强度 95.1 / 差额 46.5 / 泛用 89.8），
//              没有出现「清一色推荐高金队」。
//           ③ ⚠️ 与 2026-10-12 第 8 条那句「同样是绝境 0T，9 金队要比 16 金队强得多」的关系：
//              那一句要求**把省金算进强度**，而 2026-10-14 第 10 条**推翻了它**
//              （`docs/评分模型设计.md` v48 原话：「省金是**性价比**那一项的事，强度的第二维是
//              **投入**（投入越高越强）……这是本轮的**定义性**差别，改回去要先问用户」）。
//              本轮按**后者**执行 —— 想回到「越省金越强」要先问用户，别再自行改回 `total`。
//           ④ 行上仍留 `teamScore`（老口径整包分），但只用于**展示队分**与同分兜底排序；
//              代表整包（`best` / `unit`，卡片上那行「最佳证据」）也仍按它取，卡片文案不变。
//              补金顺序的「每抽收益」同样仍按 `total` 算（它排的是**买哪一笔**，不是队伍强度）——
//              这条没动，`team-plan-test` 里那两条顺序断言一字未改。
//           ⑤ 界面：分数来源表的 ① 那一行改成「强度分 N ｜ 0 ~ 100（绝对刻度）」，
//              表头「刻度（按候选池现算）」→「刻度」（②③ 的池内说明挪进各自的格子），
//              脚注、等式上方的说明、`index.html` 的抽卡方案说明与权重提示一并改口径。
//           ⑥ 回归：`tools/team-plan-test.mjs` 的合成夹具补 `strengthScore`，且**刻意与 `total`
//              反相关**（`k-cone` 整包分最高、强度最低）—— 这样「① 又退回按 `total` 算」会当场红
//              （与 v4.6.97「夹具不带 `versatilityRaw` ③ 就整列退化」同一个坑）；
//              改写的断言钉住「① = 该队成员里最高的那个 `strengthScore`」与「刻度是绝对 0~100」，
//              真载荷那一条**直接拿载荷里的 `strengthScore` 复算**（前 40 条逐条比），
//              另加「池内 ① 必须真的分得开（最低 < 50、最高 > 80）」。
//              `check-advice-layout.mjs` 新增判据：① 那一行必须写「强度分」+「绝对刻度」，
//              且不许再出现「队分」。
//
//   v4.6.104 用户 2026-10-15 紧接着报：「目前版本的老队伍强度得分过高，请修复」。
//            查证是**两个独立**的原因（真账号实测，强度权重拉满）：
//            ① **借用**：v4.6.103 把队伍强度取成「队内四个成员整包里 `strengthScore` 最高的
//               那一个」，而 `strengthScore` 是整包**在它自己的证据队伍**里打出来的成绩 ——
//               那支队通常**不是**眼前这支。于是「云璃E1/千冶•刃E2/花火E2/昔涟E6」显示 98.18
//               （借了昔涟在别队的成绩），它自己承载的证据只有 **13.28**；同类还有 24.29 /
//               27.25 / 46.15 / 60.63 … —— 前 20 名里 **14 支**如此。
//            ② **证据太旧**：每个副本的强度取的是**窗口内（3 版）最少行动值**那一次、
//               不按版本新鲜度取数，于是两三版前打出的旧 0 行动值一直按**当前**判据线折算成
//               满分 —— 前排那些 E6 老队（飞霄/黄泉/希儿/镜流/云璃…）的满分档几乎全来自
//               4.4/4.5，池内 ① 的 p50 被顶到 **92.5**、≥95 有 **77/219 支**、**17 支并列 98.18**。
//            改法：
//              ① `teamPlan()` 的 `strength` 跟着**代表整包**（`total` 最高、也就是承载这支队
//                 证据的那一条）走，与队分/最佳证据同一个代表；不再按成员取最高；
//              ② `frontierBoard` 的 `strengthAvHit`：跨版本从「取**最少行动值**」改成
//                 「取**版本最新**的那一次」（版本内仍取最少行动值）。比较走 `cmpVersion` ——
//                 `windowSeasons` 末尾会并进「窗口外有观测」的版本，那种可能比窗口内更新，
//                 靠循环顺序会算错。
//            实测（账号 1，强度权重拉满）：池内 ① 的 p50 **92.5 → 46.0**、≥95 **77 → 9 支**、
//              ≥98 **17 → 2 支**、前 20 名里「借用」的支数 **14 → 0**（① 与代表整包逐条相等）。
//            界面：强度来源表列名「最少行动值」→「**最近版本行动值**」，那一格下面加**版本小字**
//              （否则读者会拿旧版本的成绩来对账）；分项说明、脚注、README 的强度那一行与
//              抽卡方案的说明一并改口径。
//            回归：`team-plan-test` **31 项**（改写两条：①「队分与 ① 同跟**代表整包**走」——
//              夹具里刻意让队分低的那个成员强度分更高，改回「按成员取最高」会当场红；
//              ② 真载荷那条改成「① = 代表整包自己的 `strengthScore`」+ 反向断言
//              「① ≤ 队内最高成员的分，且至少有一批严格更低」）；`check-advice-layout` 的
//              列名契约跟着改；`strength-invariant` 10 项 / `herta` / `e2e` 177 项全绿。
//            新增对账探针 `tools/_probe-old-team-strength.mjs`（改前改后都能跑，A/B 必须逐条相等）。
//            ⚠️ v48 那句「仅取最少行动值」只在**同一版本内**仍然成立；要回到「跨版本取最快」
//              必须先问用户（与 v48 那一节的约定一致）。
//
//   v4.6.105 用户 2026-10-14 的六条清单（新建 worktree `.worktrees/versatility-per-eidolon`，
//            分支 `feat/versatility-per-eidolon`，基于 `fceaab8`）：
//
//            ① **泛用性关联到具体的星魂**（原话：「一个角色的 E0 的泛用性和 E6 的泛用性
//              其实关系不大，不同星魂需要各自比较泛用性」）。改前它是**角色级**的一个数
//              （同一个角色的 E0 包与 E6 包共用一个泛用性分）。现在：
//              · `teammateVariety` 的主体键从 `角色` 细到 **`角色|E档`**（`versatilityKeyOf`），
//                队友那一侧仍按**角色身份**计数（「不同队友」数的是人，不是 `角色|E档`）；
//              · 归一区间也改成**按档分组**（`frontierExtents.versatility.byTier`）——
//                否则 E6 那一档（投稿本来就少、原始量天然更低）会被整榜一把尺子系统性压低，
//                那就不是「各自比较」了。实测四档区间：E0 4~63 / E1 3~68 / E2 3~68 / E6 3~71。
//              · 抽卡方案的队级 ③ 随之改成「成员**各自那一档**的数」，
//                而且合成方式按用户后半句换成**成本占比加权**（下面第 ② 条）。
//              回归踩到的坑（已写进夹具注释）：按档归一之后，**只出场一支队的整包在本档
//              拿 0 分**（它是本档地板），`herta-test` 那条「最佳成绩在 E0」的夹具因此
//              自毁前提 —— 两队改成**共用同一套队友**才对。
//
//            ② **整个队伍的泛用性按成本占比加权**（原话：「整个队伍的泛用性根据不同角色的
//              成本占整个队伍的成本的权重而定」）。队级 ③ 从**简单平均**改成
//              `Σ(成员泛用性 × 该成员金数) ÷ Σ金数`；权重用**账面金数**（`datasetGoldOf`）
//              而不是「你还差几金」——用户说的是「角色的成本**占整个队伍的成本**」，
//              那是配装自己的成本结构，换个账号不该算出另一个泛用性。总金数为 0（全 4★/
//              常驻/开拓者）时退回等权平均（`teamPlan` 会被探针直接调用，除零会变 `NaN`）。
//
//            ③ **版本权重改成 `3:2.5:2:1.5:1:0.5`**（原话）。窗口从 **3 版重开回 6 版**，
//              权重线性递减（最新 3 分 → 第 6 版 0.5 分）。旧版本重新算数，但 4.0~4.2 三版
//              加起来只有 3 分、不到最新版一个人的分。界面那条脚注本来就是**从下发的
//              `seasonWeights` 现算**比例的，所以只需要同步它的兜底常量与那条 CDP 正则
//              （`[\d:]+` 不含小数点，`3:2.5:…` 会把它判红 —— 本轮实测踩到）。
//              ⚠️ **代价**：窗口一扩，进榜的「角色 × 星魂档」变多（实测 `frontierTiers`
//              242 → 258、`frontierUnits` 的逐副本明细 262 → 291），`/conclusion` 载荷
//              **596 KB → 636 KB**。两道硬断言（`e2e-test.mjs` / `team-plan-test.mjs`）
//              因此**从 600 KB 上调到 660 KB**，并在注释里写明「别顺手再往上调，
//              真需要空间先看能不能挪去按需接口」。
//
//            ④ **虚拟账号的「添加角色」→「添加/修改角色」**（原话）。`app.js` 的
//              `addCharacterCard()` 只改文案（点开的本来就是同一个角色编辑器，
//              已有角色也能改星魂/光锥）+ `index.html` 的虚拟账号面板说明。
//
//            ⑤ **「选择程序图标」里三月七（存护）的图标错了**。根因在**数据生成期**：
//              `tools/herta-i18n.mjs` 按 `name` 收口图标表，而 `1001`（存护/Knight）与
//              `1224`（巡猎/Rogue）在 StarRailRes 里都叫 `March 7th` —— 后者覆盖前者，
//              `i18n-zh.json` 的 `icons.characters` 里只剩 `March 7th → 1224.png`。
//              而 `refs.characters` 用的是**带命途的键**，于是四条「掉括号回退」的路
//              （图标选择器 / 虚拟账号编辑器 / 抽卡页 / 服务端 `resolveIcon`）一律把
//              存护指到巡猎那张图。修法：把 `virtual-accounts.js` 里本来只服务虚拟账号
//              快照的那张修正表抽成 `src/server/character-icon-ids.js`，在 `archive.js`
//              的 i18n 加载期**补出显式键**（`March 7th (Preservation) → 1001.png`）——
//              四条路一次全对，不必改任何一份前端兜底函数。
//              ⚠️ 只补**头像**：立绘 / 半身像的 1001 版没有实测过是否存在于 StarRailRes，
//              凭空改写会换来一张 404。
//
//            ⑥ **和 GitHub 上的最新发布比一比**（原话：「程序要支持与从 GitHub 比较最新
//              版本，当版本与此项目的 GitHub 版本不同时，点击提示进行更新，当版本与
//              GitHub 项目相同时，提示已是最新版本，显示此程序的版本号」）。
//              新增 `src/server/update-check.js`（纯函数 + 一次取数，14 项独立回归）
//              + `GET /api/update-check`（**只有带 `?check=1` 才真的联网**，
//              不带就只回本地版本号）+ 页脚那个「检查更新」按钮。
//              · 粘四个状态：`latest` / `update` / `ahead`（本地比 GitHub 还新，不是错）
//                / `error`（断网 / 限流 / 解析失败，都回 200 + 可读中文，界面据此分三支）；
//              · 版本比较**逐段比数字**（`4.10 > 4.6`，字符串比会反）；tag 用「抓第一段
//                数字」归一（`v4.6.104` / `hsr-4.6.104-portable` 都认），抓不到就报错，
//                **绝不拿空串去比**；
//              · 结果缓存 10 分钟（**失败也缓存**，否则断网时连点要连等 8 秒超时）；
//              · ⚠️ 这是全程序第二条「点一下才出去」的外网出口（另一条是同步黑塔网），
//                启动 / 开页面 / 切分页都**不会**触发它 —— 与 §4.4 的联网不变式一致。
//              实测（本机，2026-10-15）：GitHub 最新是 `v4.6.104`，接口回 `status: latest`。
//
//            ⑦ **每支显示的队伍一个来源视频图标**（原话：「界面上每个显示的队伍都要有一个
//              图标，点击在新界面打开对应的 b 站/油管页面，类似黑塔网（不需要内嵌播放器）」）。
//              数据一直都在：`sample.video` 实测 **11992/11992 全覆盖**（其中 **31 条**是
//              `douyin:<id>` / `tiktok:<id>` 伪串，必须按 `^https?:` 挡掉）。缺的是**投影**：
//              三条对外接口都把 `sample` 剪掉了。本轮打通：
//              · `archiveFrontier` 按「`版本|阵容`」回查 `teams[].sample`，把 `video` 补进
//                `frontierRows`（建库侧的前沿行 `{c,a,t,m}` 里**没有** id/作者/视频）；
//              · `/conclusion` **只给逐档榜的头条那一支**带 `video` —— 抽卡方案的候选池
//                就是逐档榜（实测那 242 条**完全覆盖**总榜的 77 条），而 `/conclusion`
//                只剩 ~18 KB 余量：逐条带 504 个 env 实测 622 KB。总榜那条路的队伍卡片
//                走**按需**的 `/api/archive/packs`（`enrichTipDetail` 按 `id + evidenceSeason`
