//            `update-check-test` **14 项**（新套件，fetch 注入，完全不联网）。
//
//   v4.6.106 用户 2026-10-15 的三条规则（worktree `.worktrees/old-version-chars`，
//            分支 `fix/version-weight-rules`）—— 起因是用户问「当前版本权重是符合要求吗？
//            为什么给我推荐了大量的旧版本角色」。排查结论：权重表本身符合 v4.6.105 的要求
//            （[3,2.5,2,1.5,1,0.5] 方向正确、运行中的服务就是 v4.6.105），旧角色扎堆另有
//            三个机制 —— 本轮按用户给的三条新规则逐条修掉：
//
//            ① **「已登场无成绩算 0 分」的语义确认（无代码改动）**（用户：「这个规则是让
//              老角色没上场的情况下吃惩罚，新登场角色不吃任何摊薄，其得分会因新版本的强势
//              而得高分，旧版本不参与权重」）。实测与现行实现一致：早于登场的版本不进分子
//              也不进分母；已登场无投稿的版本按 0 分进分母（老角色的惩罚）。记录进 §4.4，
//              防止下一轮把它当成 bug 修掉。
//
//            ② **泛用性按权重加权**（原话：「泛用性得分也要受到权重影响，老版本的泛用性
//              会被稀释，新登场角色的泛用性仅考虑新版本，旧版本不参与权重」）。改前它是
//              「跨副本跨版本并集的大小」（`teammateVariety.size`）——窗口 3 → 6 版后
//              老常客的队友数翻倍，花火泛用 92.3 / 瓦尔特 86.2 全是旧版本攒的。现在：
//              · `buildConclusionInner` 第一趟把队友关系**按版本分桶**（`teammateVarietyBySeason`，
//                **每个副本各一份** —— 四个副本各用一套版本号，跨副本按版本字符串并桶会把
//                不同期的队伍混进同一个集合）；第二趟与性价比/强度**共用同一个 `wSum`**
//                累计 `Σ w × 该版本队友数`，同一套两态口径（早于登场不参与、缺投稿计 0）；
//              · `frontierBoard` 再按**关卡权重**跨副本合成（分母 = 全部副本的权重和、
//                缺副本按 0 计 —— 与 `strengthTotal` 同一个形状，同一个反向激励根治点）；
//              · `versatilityRaw` 从「整数并集」变成「加权队友数」（可为小数）；
//                `versatilityMembers`（跨版本并集名单）**保留**，只作展示（来源折叠块）。
//              · 同档不同配装（不同光锥）不再共享同一个数 → teamPlan 的档位表与
//                `versatilityByTier` 都改取**档内最大**；面板来源块的验算公式改用
//                **整包自己**的原始量（拿档表那个最大值会算出别人的分）。
//              实测（账号 1，默认权重）：花火 84.3 → **74.5**（泛用 92.3 → 62.7）、
//              不死途 88.0 → 78.9、长夜月 / 藿藿跌出前 12；爻光（证据全在 4.5/4.6）
//              #9 → **#6**；千冶•刃仍 #1（它的证据本来就在新版本）。
//
//            ③ **最佳证据取「版本最新」的那一次**（原话：「最佳证据会受到跨版本发挥的
//              削减，因此还是新版本新配队更强」）。改前 `best` = 跨版本取 **score 最高**
//              的那条 —— 旧版本金数水位低、原始分占便宜，前排整包的证据几乎全是
//              4.0~4.3 的旧配队。现在与 `strengthAvHit`（v4.6.104）同一口径：**版本最新**，
//              版本内的挑选仍在 `bySeason` 填充时做（score 最高、同分限定光锥多者）。
//              连带：**「跨版本发挥」不再恒 ≤ 1** —— 分母从「最好的那一版」变成
//              「最新版那次成绩」，`> 1` = 旧版本成绩仍在抬加权平均（老常客的常态）、
//              `< 1` = 缺投稿摊薄（新角色的常态）、`= 1` = 只有最新版有证据。
//              两处脚注 / 三处断言（`herta-test` 两条 + `check-advice-layout` 一条）
//              同步改写；面板来源块 / 详情窗口的口径说明一并改。
//              ⚠️ 用户的兜底规则（2026-10-15）：**旧有规则与新规则冲突时默认采用最新版本**
//              —— 「恒 ≤ 1」那条 v4.6.78 的不变式按此作废。
//
//            回归：`herta-test` **106 项**（改三条：池=全部成绩那条用例改成钉「最佳证据
//            取最新版」+「跨版本发挥 = 1.5 > 1 合法」、真数据两条 ≤ 1 断言改成「有限正数 +
//            恒等式」）；`team-plan-test` **32 项** / `e2e-test` **187 项**（byTier 的同源
//            判据从「相等」改成「档表 ≥ 整包自己的值」，因为同档不同配装不再共享同一个数）。
//            新增探针 `tools/_probe-char-board-versions.mjs`（角色总榜 × 逐副本
//            「6 版分 vs 1 版分」对账，就是查出这三个机制的那支）。
//
//   v4.6.107 用户 2026-10-15 的一轮界面清理（worktree `.worktrees/ui-polish`，分支
