//              现在三项齐全，探针按**3 条**断言（含「与文字同行」的几何判据）。
//
//            ④ **小字更好读 / 更好懂**（用户原话：「让这个程序更高效、美观，小字部分的介绍
//              更方便用户了解程序的功能」）：
//              · 抽卡推荐页三段长篇说明改成**带标签的分行**（看什么 / 怎么算 / 队伍来源 /
//                分数怎么算 / 强度 / 性价比 / 每张卡 …），标签缩进成一列 —— 扫一眼标签
//                就知道该读哪一行（`index.html` + `app.css` 的 `.advice-note-line` /
//                `.advice-note-tag`，标签用纯文字不用色块，免得把本来就不宽的行拆碎）；
//              · 详情窗口的脚注 10.5px/1.5 → **11.5px/1.65**，条间距 2px → 4px；
//              · 「角色得分 = …」那条验算口诀给到 12.5px/1.7（它是要**照着算**的文字，
//                不是装饰性注脚）；
//              · 顺手修掉两处**已经说假话**的文案：性价比曲线指数写的是 `^1.5`（现为 1.8）、
//                强度口径写的是「最少行动值」（v4.6.104 起取**最近版本**那一次）。
//              · `advice-view.js` 里那条「补 2 金 79 分 / 补 8 金 28 分 / 补 10 金 15 分」
//                改成按 `plan.gapMax` 与 `gapPower` **现算** —— 写死的数字一改口径就失同步，
//                实测封顶 p75 → p60、指数 1.5 → 1.8 之后那三个数一个都不对了。
//
//            ⑤ **修掉 `advice-tip-window.css` 末尾一截残缺 CSS**（上一轮编辑被截断留下的
//              悬空 `padding` 与多余的 `}`），并把 `.advice-detail-inline-toggle` 收成
//              `.advice-detail-toggle.is-inline`：拆成两个类名时委托监听器与 CDP 探针都会
//              一个都找不到（折叠判据整组静默变红），合并后「一个类名」就是唯一真相。
//
//            ⑥ **本轮真正的头条：一个被 `catch {}` 藏起来的 `ReferenceError`**（CDP 套件
//              真跑之后才现形）。`versatilitySourceBlock()` 里那一行验算公式调用了 `num()`，
//              而 `num()` 只是 `scoreBreakdownTable()` **内部的局部函数** —— 模块级函数根本
//              取不到它，于是每次渲染「泛用性来源」都抛 `ReferenceError: num is not defined`。
//              更糟的是调用链外面套着 `catch { /* 取不到就用现有的那几行 */ }`（`openTip` 里
//              补明细那一步）：异常被吞掉，末尾那次 `tip.replaceWith(frontierTip(unit))`
//              整个不执行 —— **一次异常，界面上表现为三件看起来无关的事**：
//                · 「泛用性来源」永远不出现（用户这一轮点名的第 ② 条就是这个症状）；
//                · 详情表第一格的队伍**没有来源视频图标**；
//                · 逐档榜的详情页**只列一个关卡**（那正是 v4.6.96 声称已修的旧 bug 复发）。
//              修法：那一行改用与相邻两行同一套 `Number()` 写法；`catch` 加上 `console.error`
//              （**宁可打一行日志也不要静默降级** —— 这个 bug 就是因为控制台一片安静才活到今天）。
//              实测（同一个窗口、同一份数据）：泛用性名单 **0 → 78 个**、折叠块 **2 → 3 个**、
//              详情表队伍视频 **0 → 5 个**、逐档榜 E0 第一行的关卡数 **1 → 5 行**。
//
//            ⑦ **CDP 探针里三条过期判据**（都是「口径改了、判据没跟上」，与 ⑥ 是同一类病）：
//              · `versRaw` 找的是标题里的「共 N 个」，而 v4.6.106 起标题写的是
//                「**并集** N 个」（名单是并集、原始量是加权，两个量纲）；两个词都收。
//              · 那条验算公式的正则写死第一个数是 `\d+`，而 v4.6.106 起泛用性原始量是
//                **小数**（实测 27.6）→ `（27.6 − …` 一个都匹配不上；四个数一律 `[\d.]+`。
//              · 折叠块的「点开」判据原来按 `parentElement.querySelector('.advice-detail')`
//                找内容，按钮搬到第一格之后恒为 null；改走 `aria-controls`（与代码同一套）。
//              另外新增两条**真几何判据**：三条分项行各自要有内联「查看来源」按钮、
//              且与本行文字**同一行**（矩形垂直相交 + 中心偏差 ≤10px，实测 3px）。
//
//            ⑧ **界面上四十多处 `**重点**` 一直原样印着星号**（截图才看出来的）。文案是按
//              Markdown 习惯写的，而 `text()` 用的是 `textContent` —— 于是
//              「角色得分 = …」那一行实际渲染成 `但**最小 / 最大取本星魂档自己那一把尺子**）`。
//              给 `text()` 加了一个**极简行内富文本**：成对的 `**…**` 渲染成 `<strong>`，
//              其余一律按纯文本（**从不拼 HTML 字符串**：命中片段走 `createElement` +
//              `textContent`，数据侧字符串即使带 `<` `>` 也不存在注入面）。
//              没有 `**` 时走快路径 `textContent`，与改前逐字节相同；星号落单时也退回纯文本
//              （宁可留着星号，也不要吃掉用户看得见的字）。一次改动覆盖全部 40+ 处。
//
//            回归：**21 个套件里 20 个全绿**（含真跑的 CDP 布局套件！）。唯一的红是
//            `team-plan-test` 那 3 条**上一支 worktree 带进来的口径改动**（见 ⓪）；
//            CDP 套件剩 1 条红「角色总榜受抽卡权重影响」，**main 上同样红**（复现步骤见
//            HANDOFF §4.2AH 末尾）—— 那是另一条待查的线索，不是本轮引入的。
//            详见 HANDOFF §4.2AH。
//
//   v4.6.108 用户 2026-10-15 的一句提议：「可不可以让**性价比过低的得分改为负数**，
//            这样不会报红」—— 一句话同时解决了上一轮留下的口径争议与 3 条红里的 2 条。
//
//            **改法**：②性价比那条曲线**0 以下不再截断**。
//              旧：`clampUnit(1 − 补金 ÷ 封顶) ^ k`（0 以下压成 0）
//              新：`sign(t) × |t| ^ k`（t = 1 − 补金 ÷ 封顶），幅值截到 1 ⇒ **值域 [−100, 100]**
//            ⚠️ 不能直接写 `t ** k`：**负数开小数次方在 JS 里是 NaN**（这正是一条团队测试
//              「3 金 ÷ 封顶 1 金」原本算出 NaN 的由来）。必须取绝对值再补符号。
//            ⚠️ 幅值截到 1：不截的话「补 40 金的队」能把总分拽到 −300，抽卡权重就失去意义。
//            ✅ **正分那一段逐值未变** —— 所以「补 1~2 金几乎不受影响」与「10 金归零」
//              这两个既有诉求都不受影响，变的只有超封顶那一段。
//
//            **为什么这不是「为了让测试变绿而改代码」**：截断在 0 有一个真实的恶性后果 ——
//            所有「补金 ≥ 封顶值」的队伍**全都是 0 分**，那不是惩罚贵队，而是**取消了这一项
//            的区分度**（贵队之间再也分不出高下）。于是排序退化成只剩 ①强度 与 ③泛用性，
//            而这两项**都不看金数**（① 是「打得多好 + 投入越高越高」）。实测（空账号池、
//            封顶 17 金）：
//
//            | | 截断在 0（改前） | 接通负分（现在） |
//            | --- | --- | --- |
//            | 第 1 名账面金数 | **21 金** | **11 金** |
//            | 前 8 名账面金数之和 | 174 金 | **105 金** |
//            | 前 8 名里 ② = 0 的支数 | **5 支** | 1 支 |
//
//            **连带把指数 ^1.8 收回 ^1.5**（这是让「不会报红」真正成立的那一步，用户可推翻）：
//            接通负分后 `team-plan-test` 只剩 1 条红 ——「**补 2 金的 ② 不该被指数砍掉太多**」
//            （沿用线性基准 −8 分的容差）。实测 ^1.8 把补 2 金的 ② 从线性的 85.7 砍到 75.7
//            （**10 分**，越界），^1.5 是 79.4（8 分以内）。而 `SCORING.teamPlanGapPower` 的
//            注释里写的口径本来就是「越贵扣得越狠，而**小差额几乎不动** —— 不是把整条曲线压
//            下去（那会连补 1~2 金的队伍一起罚）」：^1.8 已经不满足这条，^1.5 满足。
//            ⚠️ 用户若更想要 ^1.8 那种陡尾部：把那条断言的容差从 8 放宽到 11 即可，
//            但那是**放弃**「小差额几乎不动」这条自己定过的口径，应当由用户拍。
//
//            **同步改过的东西**（口径动了、文案/探针/测试必须一起动）：
//              · `advice.js`：曲线本体 + `SCORING.teamPlanGapCapPct` / `teamPlanGapPower` /
//                `teamPlan()` 大注释 / 下发字段注释（值域与「正好到封顶 = 0 分」）；
//              · `advice-view.js`：卡片脚注（含取样点改成**现算**并补一个超封顶的负分例子）、
//                详情窗口刻度行（顺带修掉写死的「池内 p75」→ 现取 `gapCapPct`）、
//                窗口脚注、`gapSample()` 改成与生产同形（含负号）；
//              · `index.html`：抽卡推荐页那一段小字；
//              · `tools/team-plan-test.mjs`：`caret()` 复算函数、用例名、超封顶那段断言
//                （从「≥ 封顶 → 0」改成「> 封顶 → 负分且 ≥ −100」+ 三条纯函数性质，
//                避免那条循环在池内没有贵队时**静默空跑**）；
//              · `tools/team-plan-cases.mjs`：② 的取值范围改成 [−100, 100]；
