//               「先跟自己取 max」，结果**强度不变式当场红** ——
//               `Tribbie: E1C0(87.7) > E1C1(86.4)`（951 组可比档位里翻面 1 组）：
//               自身 91.84 的那档豁免了天花板、而投入更高的那档（借来的兜底被压到 90）
//               没豁免，1.84 分的差 > 投入项那一步 0.45 分 → 直接违反用户 2026-10-14
//               点名的「投入越高强度不可能更低」。
//               定性：`strengthTotal` 是**逐关卡**两档的加权平均（某一关 0 行动值 = 100、
//               其余关不是），所以自身落在 (90, 100) 是**规则允许**的；而「没打出 0 行动值
//               的队伍，再好也够不到顶格那一档」（用户 2026-10-16 第 1 条）要求第二档在
//               **整包层也封顶 90**。所以那一刀是**两档天花板**、不是包络越权，
//               正确写法就是当前的 `floor = min(max(自身, 兜底), 90)`。
//               本轮只落两件事：① `advice.js` 的注释改写成上面这套定性（删掉「只砍越档
//               的那部分、档内的兜底一字不动」那句错话）；② **详情窗口补一条小字** ——
//               自身合计越过 90 时写明「非顶格档的上限就是 90，所以这 95 分按 90 算」
//               （不写，读者拿表里的「本档自身合计」对账就会以为算错了）。
//               回归：`herta-test` 新增一条夹具（同角色三支整包：E0+金光锥 / E2+金光锥 /
