//
//   v4.6.130 2026-10-19：**抽卡推荐系统整体重构**（需求文档《抽卡推荐重构》，
//            分支 `feat/rebuild-gacha-advisor`）。旧算法（逐档榜 ∪ 总榜 ∪ 行动值前沿
//            三池拼候选、浏览器端 `teamPlan()` 加权、0~100 归一上下限）整条下线。
//
//            * **v2 评分内核**（`src/server/gacha-score.js`）：
//              行动值型 `strengthPart = ws × (1 − 行动值/500)`，轮次型 `ws / (轮次+1)`；
//              `costPart = baseline(该版本最低金) / c`，∈ (0,1]，0 金队拿 1、无基准 0。
//            * **角色总榜**（§3）：整包按版本加权平均（分子分母规则见设计文档 §3.5），
//              「每角色只留一条」的收敛移到服务端 —— 抽卡权重从这一版起**必须进服务端**。
//            * **抽卡方案**（§4，`src/server/gacha-plan.js` + `gacha-plan-run.js`）：
//              只算**一个关卡**（默认绝境），逐版本取**最大值**乘版本权重；
//              Δgold = 0（已齐）照样进榜、性价比项取 1。
//              **合并判据两层**：聚合身份 = 整包键（`rosterKeyOf`，差一个叠影是另一条
//              成绩）；**交付折叠 = 角色组合**（`lineupKeyOf`，用户 2026-10-19 确认）——
//              同一套四人只占一行，其余配装收 `variants[]`（轻字段，不跑补金明细）。
//              实测 936 整包 → 267 角色组合，前三名不再重复。
//            * **新路由** `POST/GET /api/archive/plan`；**上场率**（§5）
//              `archiveUsage()` 5 副本全展开 × 4 类环形图（`advice-usage.js`）。
//            * **前端**：`renderTeamPlan()` 重写（数据全来自服务端，浏览器不再有一份
//              加权实现）；分数印 **toFixed(2)**；`fill` 光锥中文名修复（按 kind 分流
//              查 `lightCones` 表）。外观改动按需求文档：标题改「角色和配队 · 抽卡推荐」、
//              删「按星魂档」与说明段、关卡权重 → 关卡选择（5 选 1 下拉，默认绝境）、
//              抽卡权重删泛用性（默认 1:1）。
//            * 性能：10 万条最坏 343ms；`runPlan()` 真实数据 380ms（缓存成员/整包成本 +
//              次选倒排扫描上限 400）。
//            * 回归：`gacha-plan-test` 81 项（+12 折叠）、`gacha-score-test` 96、
//              全量 23/26 套件绿（3 个失败是本机沙箱 `spawn UNKNOWN`，与代码无关）；
//              CDP 浏览器验收 20 卡零报错。
//
//   v4.6.129 2026-10-18：**回退 v4.6.128 的版本折价 + 改按「0 行动值达成率」给顶格档
//            折价**（用户：「回退就行，然后再解决一下老队伍角色的队伍强度过高的bug，
//            那个丹恒·饮月得分过高了」）。
//
//            ① **回退 v4.6.128 的 `versionFactorOf`**（那一版方向就是错的，详见下）：
//               删掉新增的 `seasonWeightsOf` / `versionFactorOf`（约 46 行），
//               `envStrength` 回到 `100 − pinch`；`advice-view.js` 的「旧版本成绩按
//               版本权重折价」文案一并撤掉。**保留** v4.6.128 的另一条修复（同一个
//               金数只印一次）—— 那是独立的、正确的，用户没要求回退它。
//
//            ② **「老队伍强度过高」的真正根因不是版本，是副本难度**
//               （用户报「4.6 绝境有 0 行动值的队伍」纠正过一次，我最初判错了）：
//               §4.1 的顶格档一直是「行动值 = 0 → 100 分」，但**「0 行动值」在不同副本
//               难度差一个数量级**。实测达成率（`tools/_probe-zero-av-rate.mjs`，新，
//               分母 = 全部有通关记录的队伍）：
//                 混沌回忆 moc 4.5    308/316 = 97.5%   ← 九成队伍的日常
//                 异相仲裁 aa 4.6    374/404 = 92.6%
//                 末日幻影 as 4.6     73/247 = 29.5%
//                 异相仲裁·绝境 4.5    6/132 =  4.5%   ← 该期行动值中位数 296
//               绝境**权重 5**（其余四关各 1）且是唯一有 0 行动值记录的副本 ⇒
//               **只打了绝境的老队分母 = 分子 = 5，直接拿满 100 分**，比当期（4.6）真
//               打了绝境的队（94~97）还高。丹恒•饮月 E2/花火 E2/缇宝 E0/瓦尔特 E2
//               那支队（`moc@4.1`，0 行动值，123/133 支队都能做到）就是这样虚高的。
//               修法：**顶格上限按达成率折价**
//                 上限 = 100 × max(strengthTopBandFloor,
//                                   strengthTopBandRare + (1 − strengthTopBandRare) × (1 − rate))
//                 默认 rare = 0.05 · floor = 0.35
//               折出来：绝境 4.5 → 95.7 · 末日幻影 4.6 → 71.9 · moc/aa/pf → 35.0（保底）。
//               ⚠️ **floor 不能取 0**：纯线性 `100 × (1 − rate)` 把 moc/aa 压到 8 分，
//               实测 1089 支「只打了 moc/aa 一关」的队均分15.4 → **3.4**、整批沉底。
//               ⚠️ **高分区不受影响**：折价只作用于 `av == 0` 那一行，而实测85~95 区间
//               全是绝境队（有 `av > 0` 成绩），折价前后该区间行数几乎不变（110→110）。
//               ⚠️ **「0 行动值队登顶」这条不变式保住了**（用户 2026-10-16 第 2 条）：
//               实测「仅看强度权重」时第 2~4 名仍是绝境 0 行动值队（95.6），紧贴在第一
//               名 97.4 之下 —— **难度驱动**的排序，不是版本驱动的。
//
//            ③ **v4.6.128 为什么是错的方向**（留档，别再走一遍）：
//               `versionFactorOf` 折的是**版本**，但老队虚高的机制是**副本难度**。
//               实测那条折价把AV 池整体压到 ~75 以下，而**未被折价**的 Tier 池
//               以 97.4 反超登顶（「仅看强度权重」时第一名整个换人，用户报「又搞错了」）。
//               根因是三条链量纲不齐：Tier 链的 `unit.strengthScore` **本身已含**
//               跨版本加权（v4.6.125），而 AV/ALL 链是客户端自算、v4.6.128 只折了后者
//               —— 两条链的版本惩罚力度不同。本次教训写进 `.workbuddy/memory/MEMORY.md`。
//
//            ④ **数据通路**：`zeroAvRateByEnv` 由 `conclusion.js` 的 `collectAllTeams`
//               顺带统计（口径 = **队 × 副本**，同一支队出现在多个整包里不能逐整包
//               累加；也**不能用** `zeroAvGoldBySeason` 那套前沿行，每关每版只留最好
//               的几支会严重偏低），经 `/api/archive/teams` 下发 —— **界面的抽卡方案
//               只走这条路由**。`/conclusion` 因 660 KB 上限不带 allTeams、也就没有这个
//               字段，此时 `topCapOf` **退回 100**（老载荷 / 合成夹具同理）：
//               宁可不做这个折价，也不要猜一个更低的顶格。
//
//            回归：`team-plan-test` 40 → **45 项**（删掉 v4.6.128 的 A0b 三条，新增 A0c
//            四条：`/conclusion` 不带达成率且退回 100 / `/api/archive/teams` 带且口径合法
//            / 绝境顶格上限必须高于 moc·aa / 折价端点与单调不反超 / 折价后 0 行动值队
//            仍站得住）。探针：`tools/_probe-zero-av-rate.mjs`（新）。
//
//   v4.6.128 2026-10-18：**老队伍强度折价 + 全队金数只印一次**（分支
//            `fix/old-team-strength-and-gold-dup`；用户：「抽卡方案给的配队有些会再显示
//            一次全队金数，不要重复显示……有些老队伍的队伍得分异常，请排查问题」）。
//
//            ① **老队伍得分异常（真 bug，口径遗漏）**：抽卡方案有**三条**候选路径 ——
//               逐档榜（代表整包）、行动值前沿（`avTeams`）、全队伍表（`allTeams`）。
//               v4.6.125 给强度恢复版本加权时**只改了第一条**，后两条仍是
//               「只看本队自己的行动值」，于是老版本的成绩按满分计：
//                 * 实测（中配账号）一支只有 **4.4** 期成绩的队（飞霄/不死途/缇宝/
//                   千冶•刃）在这一池拿 **92.7**，同一支队在逐档榜那条路上只有 **48.7**；
//                 * 用户截图那张卡是 4.1 期的队（丹恒•饮月 E2 / 花火 E2 / 缇宝 E0 /
//                   瓦尔特 E2），「队伍强度」印着 **89.7** —— 就是这条链。
//               修法：新增 `versionFactorOf(hit)`，逐关强度乘上
//               **该版本权重 ÷ 该副本窗口里权重最大的那一版**（默认表下当前版本 1.00、
//               4.4 → 5/6、4.1 → 2/6）。效果：那支 4.4 期的队 92.7 → **61.8**，
//               「证据落后 ≥2 版却 ≥70 分」的行从一批降到 **0**。
//               ⚠️ **刻意不照抄逐档榜的「缺版本按 0」**：前沿池本来是用来捞 0 行动值
//               队伍的，除以整窗权重会把它压到 ≤29 分、等于取消这一池（§4.5）。
//               ⚠️ `avTeams` 每关 8 支实测**全是旧版本**（moc 4.1~4.3、绝境全是 4.5），
//               所以折价后这一池整体落在 ~75 分以下、前排由逐档榜承接 —— 这是口径的
//               必然结果（用户 2026-10-18 晚「满分应当是非常难的」），不是回归。
//               想让「0 行动值队伍」重新登顶要改 `avTeams` 的**选行**（按版本优先）。
//
//            ② **全队金数印两遍**：卡片第一行是「账面 8 金｜补金 6 金」，紧接着的
//               「最佳证据：混沌回忆 · 0T · **8 金** · 4.1 版本」又印一次 —— 而两者量的
//               本来就是同一个数（账面 = 这套配置的金数，方案的目标档位就是投稿那一档）。
//               实测 500 张卡里 **42 张**会印出两个一模一样的金数。修法：证据金数只在
//               **与账面不同**时才补印（目标档位 ≠ 投稿档位的情况才有信息量）。
//
//            回归：`team-plan-test` 42 → **43 项**（新增 A0b 三条：当前版本仍 100 /
//            4.1 → 1/3 且 4.3 更高 / 没有 `seasonWeights` 时不折价；真载荷那两条按新口径
//            重写 —— 原判据「前 5 里必须有 ≥95 的前沿队」钉的正是旧口径）；
//            `herta-test` 新增源码级护栏（「最佳证据」那段必须拿 `displayGold` 比对）。
//            探针：`tools/_probe-plan-audit.mjs`（新，一次跑出两条 bug 的现场）。
//
//   v4.6.127 2026-10-18：**抽卡方案显示 bug 修复（视频图标 + 副本量纲去重 + 0 金）**
//            （用户：「很多队伍没显示视频图标；末日幻影的积分和行动值重复了，就写具体
//            积分就行；混沌回忆、虚构叙事、异相仲裁 · 王棋和骑士关不存在行动值记录，
//            不用写 0 行动值」＋截图「很多队伍会再写个 0 金，这一行不要显示」）。
//
//            ① **allTeams 全队伍候选池补回视频图标**：服务端 `collectAllTeams` 用视频
//               地址字典去重，前端按索引回查 `conclusion.allTeamVideos`。修复前 allTeams
//               4113 支队伍全为 `video: null`， cards 自然画不出来源图标。
//            ② **卡片「最佳证据」文案按副本真实量纲写，并去掉重复档位**：
//                 * 末日幻影 → `积分 3864`（内部 av = 4000 − 积分），不再写「行动值 136」；
//                 * 混沌回忆 / 虚构叙事 / 王棋和骑士关 → `0T` / `2T` 等，不写「行动值 0」；
//                 * 绝境王棋关 → 继续写 `行动值 240`（这是它真正的量纲）。
//               实现：新增 `metricValueTextOf(mode, stage, internalAv)`，从内部 av 直接
//               翻出带单位的文案；卡片/总榜行/副本 chip tooltip/配队清单统一用
//               `scoreTextOf` 合并「档位 + 具体成绩」，避免同一行里「积分 ≥3700 · 积分 3864」
//               这种重复。
//            ③ **附赠修复**：`perfCurveText` 脚注原来把内部 av 传给 `metricValueText`
//               （它吃游戏空间值），末日幻影脚注会印成「积分 0 / 300 / 600」；现改用
//               `metricValueTextOf` 翻回「积分 4000 / ≥3700 / ≥3400」。
//
//            ④ **不再印「0 金」**（用户截图）。两层根因，缺一不可：
//               * `advice.js` 的 allTeams 解析把 `cost` 写成了 `0`（它其实没有金数数据）；
//               * `advice-view.js` 用 `Number.isFinite(Number(b.bestTeamGold))` 判空 ——
//                 `Number(null) === 0` 与 `Number('') === 0` **都是有限数**，
//                 于是「没有这一项」被当成「0」照印。
//               修法：allTeams 侧写 `null`；视图侧新增 `hasNumber()` 并把**金数**判空
//               全部改走它（卡片 / 总榜行 / 副本 chip / 配队清单）。
//               ⚠️ **判据只圈金数**：权重、档位系数、分位区间那些地方
//               `Number.isFinite(Number(x))` 是对的 —— 那里「缺失 = 0」本就是口径
//               （权重 0 = 该关不进分母）。一刀切会误伤十几处正确写法，已在
//               `herta-test` 的源码级护栏里注明。
//               实测：500 支下发里「0 金」从 406 支降到 **0 支**；这 406 支确实来自
//               allTeams（本身没金数，省略是对的），由新增的 `allTeamsSource`
//               标记区分 —— 该标记也补进了行投影，否则探针分不清「正常省略」
//               与「数据链路掉了」。
//
//            回归：`herta-test` 新增 5 条 `metricValueTextOf` 断言 + 一条源码级
//            护栏（金数判空不许用 `Number.isFinite(Number(...))`）；`team-plan-test` 40 /
//            `strength-invariant-test` 21 / `version-weight-plan-test` 19 全绿。`e2e-test`
//            仍因本机 DPAPI `spawn UNKNOWN` 环境性失败，与本次改动无关。
//
//   v4.6.126 2026-10-18：**搜索框支持多个关键词（AND = 同时包含）**
//            （用户：「搜索框应当支持多个关键词或者多个角色/光锥的搜索，给出同时包含
//            这些词的搜索结果」，接在 v4.6.122 的两个搜索框、v4.6.124 的真实名次之后）。
//
//            ① **`queryTermsOf(value)`**（`advice-paging.js` 新）：把输入框那一串按
//               **空白 / 中英文逗号 / 顿号 / 加号 / 竖线**拆成若干个关键词，逐个小写。
//               空格是主分隔符 —— 中文输入法选字候选之间就是空格，用户最自然就是敲空格。
//            ② **`matchesQuery` 改成 AND**：逐个 term 都 `includes` 才算命中。
//               为什么不是 OR：「流萤 银狼」要的是「**这两个都有**的队伍」；OR 会把
//               「只有流萤」和「只有银狼」全倒出来，等于没筛。
//               ⚠️ 单关键词的行为**逐字不变**（`every` 对一个元素等同于原来那个
//               `includes`），所以两个搜索框以前的用法都不受影响。
//            ③ **文案跟着说清**：两个输入框的 placeholder 改成「搜索角色 / 光锥
//               （空格分隔多个 = 都要有）」；状态行多词时印「搜索「A + B」（同时包含）
//               命中 N 支」—— 只印「搜索「A B」」的话，读者分不清是搜一个长名字还是
//               两个词都要有；空态也改成「没有队伍**同时**包含「A + B」…」。
//            ④ 「只敲了分隔符」（例如 `  ,  `）按**没搜索**处理（`terms.length === 0`），
//               不白跑一次 filter。
//
//            回归：`paging-test` 47 → **64 项**（新增 17 项：6 种分隔符、大小写、AND 而非
//            OR、角色+光锥混搜、词不必相邻）；`check-advice-layout` 新增两条真点击判据
//            —— 敲「千冶•刃 停云」实测**命中 1 支且每张都同时含两者**，再加第三个词后
//            结果只会更少（AND 单调性）。全量 23 套件仅两个环境性失败（凭证 DPAPI /
//            e2e 的 `spawn UNKNOWN`）。
//
//            ⚠️ 写判据时踩过一次坑：单调性那条我一开始写成「`A + 第三词` 的条数 ≤
//            `A + B` 的条数」，那是**两个不同的查询**，条数本来就没有可比性（实测 1 张
//            vs 11 张，看着像 bug）。正确写法是**同一组词上加词**再比，已在注释里钉住。
//
//   v4.6.125 2026-10-18：**强度恢复版本加权 + 顶格档按金数小幅区分（解决并列第一）**
//            （用户：「由于存在版本权重，强度权重要完全拿满分应当是非常难的，并且每期的
//            强度最高分都有且仅有一个队伍（0 行动值的同时金数最低），请解决这个问题」）。
//
//            背景：v4.6.121 那轮把强度改成了「只看最快」（某一期 0 行动值 → 这一关 100、
//            不再按版本权重平均），加上环境级继承补分，结果 81 条整包里 **17 条并列 100**、
//            名次退化成字典序 —— 用户报「当仅存在强度权重时，大量角色并列第一」。
//
//            ① **恢复版本加权**（`frontierBoard` 第二趟）：该副本强度从「取最快那一行」
//              改回 `Σ(版本权重 × 该版本强度) ÷ Σ(版本权重)`（`accStrength / wSum`）。
//              满分因此要**跨多个版本**都 0 行动值 —— 有版本权重在，满分自然极难。
//              抽卡方案 avCandidates 的 `withStrength` 同源（本来就按副本权重加权，
//              这里只是把「0 行动值 = 100」改成「0 行动值按金数降」）。
//
//            ② **顶格档（0 行动值）按金数小幅区分**（新增 `SCORING.strengthGoldPinch = 0.1`）：
//              ```
//              该版本该关强度 = av == 0 → 100 − 0.1 × max(0, 本队金数 − 该期最省金)
//                              否则     → 95 × 强度曲线（不碰金数）
//              ```
//              「本队金数」用 `storedCost`（隐金前原始金数），「该期最省金」用
//              `zeroAvGoldBySeason[版本].min`（**0 行动值队伍**的最省金，不是 perfect 档
//              最省金 —— 用户要「0 行动值的同时金数最低」）。每多 1 金只扣 0.1 分：
//              最省金那支 = 100（唯一满分）、贵 10 金仍 99 —— 满分唯一可排序，又不会像
//              v4.6.110 那样把 18 金的 E6 队折到个位数（那是被用户 2026-10-17 推翻的旧口径）。
//
//            ③ 修后实测（只看强度，81 条整包）：**0 条 100**、最高 **99.24**（砂金•戏浪
//              E6S5），知更鸟 98.65 / 昔涟 98.40 / 长夜月 97.92 / 风堇 97.63 …… 名次完全
//              拉开，不再并列；p50 64.1、p90 97.0、≥90 的 22 条。
//
//            回归：`herta-test` / `team-plan-test`（40 项）/ `version-weight-plan-test`
//            （19 项）/ `strength-invariant-test`（21 项）全绿。测试里「只看最快」「金数
//            不参与强度」「版本权重不影响强度」那批旧断言按新口径重写（`strength-invariant-test`
//            的 ②-A/②-B/②-C 段、`team-plan-test` 的 A0 段「混合成绩」期望值）。
//
//   v4.6.122 2026-10-18：**抽卡方案列全池 + 分页，两个榜各加一个搜索框**（用户「目前抽卡

//   v4.6.122 2026-10-18：**抽卡方案列全池 + 分页，两个榜各加一个搜索框**（用户「目前抽卡
//            方案仅提供了 15 个配队，我希望改为提供尽可能多的配队，为此可以进行分页显示配队，
//            每页显示 20 个配队；为角色总榜和抽卡方案添加 2 个搜索框，能够根据角色或光锥
//            名称进行搜索」）。
//
//            ① **下发上限 15 → 500（= 实际不截断）**（`SCORING.teamPlanMaxRows`）。
//               本机实测候选池 **284 支**（`_probe-team-plan-perf.mjs`），所以「尽可能多」
//               就是全池。500 只是兜底：池子异常膨胀时不至于把浏览器撑爆。
//               ⚠️ 界面上**一次只画 20 张卡**（`TEAM_PLAN_PAGE_SIZE`），不是「一次画 284 张」
//               —— 后者是**近万个 DOM 节点**，主线程会明显卡顿。这是本轮性能的硬约束（按节点规模
//               定性；本机起不了浏览器，没有帧率/耗时实测）。
//
//            ② **分页**（`advice-view.js` 的 `renderTeamPlanPager`）：上下各一条翻页条
//               （一页 20 张卡要滚很远），页码窗口化（首末页 + 当前 ±2 + 省略号，恒定
//               ≤9 个格子），只有一页时整条隐藏；翻页后回到列表顶部；卡片名次用**全局**
//               序号而不是页内序号。纯算术抽到 `public/scripts/advice-paging.js`，
//               由 `tools/paging-test.mjs`（40 项，离线）钉住。
//
//            ③ **两个搜索框**：角色总榜（工具条右侧）与抽卡方案（工具条左侧）。匹配规则
//               中英名 + 光锥名都认（`searchTextOf`）、子串匹配（只记得中间一段也命中）、
//               大小写与首尾空格不敏感；输入法组字期间不触发（否则拼音字母会把榜面筛空）；
//               120 ms 防抖；`type=search` 的 × 与 ESC 都能清空。搜索**只过滤、不重排**，
//               名次仍是榜单名次；方案换词时回第 1 页（否则会停在空页上）。
//
//            ④ **性能**（用户「你需要保证该程序的性能」）：改口径前先量了一遍 ——
//               `teamPlan()` 全池 **39.5 ms**，其中三处是「按 15 条写没感觉、按 284 条就露馅」
//               的 O(n²)：
//                * `charScoreOf()` 每次 `units.filter()` 扫一遍（候选数 × 补金笔数 + 下发
//                  条数 × 成员数 ≈ 1800 次 × 81 个单位）→ 改成**预建一次 `Map`**；
//                * `alternatives` 每条都对全池 `filter → map → sort` → 改成**按成员倒排
//                  索引**，只碰「至少共享一个成员」的那几十支；
//                * 视图侧把 `teamPlan()` 的结果**按输入签名缓存**：翻页 / 搜索只重建 20 张
//                  卡，不重算全池；搜索用的 haystack 也随缓存复用。
//               实测：**39.5 ms → 22.2 ms**（`node tools/_probe-team-plan-perf.mjs --check`），
//               并且 `--check` 把 284 条的 `alternatives` 与**旧算法**逐条对拍
//               （前 3 支的 key 序列），**0 条不一致**。
//
//            ⑤ `team-plan-test` 的那条断言跟着放宽：它原来断言「每支队伍的总分都在 0~100」
//               —— 那只在「只下发前 15 条」时成立。现在整池都在，尾部「补 30 金」的队伍
//               ② 是负分（2026-10-15 起 0 以下不截断），总分可以为负，那正是它们真实的
//               位置（最后一页）。改成断言「各分项在自己的刻度内 + 总分 = 三项加权和 +
//               池里确实存在负分队伍（否则说明又被截断了）」。
//
//            ⚠️ **CDP 布局套件本轮没跑**：本机沙箱不允许 `spawn powershell`，而
//            `bin/serve.mjs` 启动时要 DPAPI 解密账号库 → `启动失败： spawn UNKNOWN`
//            （见 `docs/CDP布局套件.md` §2.1）。所以新增的翻页条几何 / 搜索框宽度
//            **没有**经过真浏览器验证；`run-tests.mjs` 里那一套照旧「跳过 + 只做语法自检」。
//            下一次能起 9222 时应当补跑，重点看：`.advice-plan-toolbar` 在 1280 宽下是否换行、
//            翻页条是否把「候选 N 支」状态行挤下去。
//
//   v4.6.124 2026-10-18：**搜索结果显示真实排名** + **两个工具条靠左、选择按钮在左**
//            （用户原话：「搜索框和选择页面框都应当位于界面左侧，且两者是选择按钮在左，
//            搜索框在右；搜索到的结果应当显示其真实的排名，而不是重新开始算」，
//            接在 v4.6.122 的「整池 + 分页 + 两个搜索框」之后）。
//
//            ① **真实名次**（`advice-paging.js` 新增 `withRealRank(source, matched, keyOf)`）：
//               搜出来的行印**完整榜里的名次**，不再是「筛选后第几条」。
//               改前两处都从 1 重排 —— 抽卡方案是 `start + i + 1`、总榜是 `i + 1`；搜索一敲，
//               第一张卡就印 `#1`，读起来就是「它在榜上排第 1」（实测搜「银狼LV.999」命中
//               24 支，真实名次是 `1, 8, 16, 20, 31, 39 …`，改前全是 `#1 #2 #3`）。
//               没有搜索时两者相等（那时 `start + i + 1` 就等于真名次），所以**名次没变、
//               只有搜索后的显示变了**。名次仍是视图的事：搜索 / 翻页都不许改写它。
//            ② **工具条布局**：两个 `.advice-*toolbar` 的 `justify-content` 从
//               `space-between` 改成 `flex-start`，去掉 `.advice-unit-toolbar-side` 的
//               `margin-left: auto`（它正是把「搜索框 + 状态行」推到最右的那一下）；抽卡
//               方案的 DOM 子节点顺序对调为「翻页条（选择按钮）→ 搜索框」。合起来就是用户
//               要的那句：整块从左侧起排、块内选择按钮在左搜索框在右。
//
//            ③ **CDP 套件**：新增四组判据（工具条贴左、选择按钮在左、两处搜索的真实名次）；
