//               40-40-20」实际早该是 **4:5:1 / 40-50-10**（v4.6.121 换的默认值），
//               此前因为本机跑不了 CDP 套件一直没人看见。**这两条只改测试文字、不动口径。**
//
//            回归：`paging-test` 40 → **47 项**；`check-advice-layout` **全部通过 ✓**
