//
//   v4.6.120 2026-10-17：**版本权重的档位可增删**（用户「添加两个按钮，让用户可以点击按钮
//            添加更多的版本权重，或者点击删除最后一个版本，这样会有更多或者更少的版本权重」）。
//
//            改前的形状是「权重表恒 6 档」：`VERSION_WEIGHTS` 定长、`versionWeightValues()`
//            恒按 6 个槽位读、服务端两条链的窗口长度钉在 `VERSION_WINDOW`（6）。于是
//            「加一版」这件事在四个地方同时做不到 —— 界面没地方加、读数只认 6 档、
//            请求体也只发 6 个数、服务端就算收到 8 个数也只取窗口内 6 版。
//
//            ① **表定义改成「档位数可传」**（`public/scripts/advice.js`）：
//               新增 `versionWeightRows(count)` / `versionWeightDefaultAt(index)` /
//               `versionWeightCountOf(input)`；`versionWeightDefaults(count)`、
//               `versionWeightValues()`、`normalizeVersionWeights()` 全部**保住入参的档位数**。
//               第 7 档起的默认权重**沿用最后一档 0.5**（归零 = 那版不进窗口，与「加一版让
//               它参与」的意图正好相反）。`VERSION_WEIGHT_ROWS` 保留为「默认 6 档」那一份，
//               老调用点（界面 / 服务端 / `herta-test` 的槽位名断言）逐字不变。
//            ② **上下限 1~12**（`VERSION_WEIGHT_MIN` / `VERSION_WEIGHT_MAX`）：本地数据集
//               里最长的副本（混沌回忆）15 版、其余 10~13 版，12 档已够；下限 1 保证整条链
//               至少有一档。
//            ③ **服务端窗口跟着档位数走**（`src/server/archive.js` 的 `archiveFrontier` /
//               `resolveScope`、`src/server/conclusion.js` 的 `conclusionEnvs` 与两处
//               `archiveFrontierAll` 的 `window`）：原来 `windowSize` 的上限是
//               `Math.min(选项, VERSION_WINDOW, versions)` —— 加了档位也进不来，按钮等于
//               没接线。实测 8 档时五个副本的 `versionWindow` / `seasons` 都从 6 变 8。
//            ④ **界面**（`public/index.html` / `advice-view.js` / `styles/app.css`）：
//               版本权重小标题右边两个按钮「加一版 / 删一版」+ 版数标签（`6 版`）；
//               到 12 / 1 时 `disabled`。加档用 `[...current, 新档默认]` —— **不许**用
//               `versionWeightDefaults(n+1)` 整张重置（那会把用户调过的权重全抹掉）。
//               读数按**网格里的输入框个数**走（不再按恒 6 档的 `VERSION_WEIGHT_ROWS`）。
//               按钮不防抖：点一次就重算（`packsCache.clear()` → `loadConclusion()`，
//               与三处权重旋钮同一套收尾）。
//
//            ⚠️ **存档形状的口径分两种**：数组（现在这套界面自己写的）→ 长度**就是**档位数
//               （「删一版」存下来的是短数组，补齐到 6 等于按钮没反应）；对象（`{'0':3}`
//               这种老形状，界面从没写过它）→ 至少补到 6 档再按默认补齐（老口径不变）。
//            回归：`version-weight-plan-test` 新增 D 段 6 项（档位默认值 / 槽位名 / 保档位 /
//               上下限 / 8 档窗口 / 3 档窗口），`_probe-ui-version-weights` 新增 ⑥ 13 项
//               （真 click 事件 → 7 个框 / 已有数值不动 / 请求体 7 档 / 上下限 / 短数组）。
//
//   v4.6.120 2026-10-17（四个分支合进 main 时补的）：**`/conclusion` 载荷削重** ——
//            强度 / 泛用性 / 性价比 / 版本权重这四个分支是**并行**开发的，各自都在载荷里
//            加过字段（整包级 `inheritedSeasons`、三条 `ownGold`、各档位的 `power`），
//            合起来之后默认 6 档的载荷到了 **661.5 KB**，顶穿 `e2e-test` 那道
//            **660 KB** 护栏；而档位可增删之后拉到 12 档是 **713.7 KB**。
//            ⚠️ 这道护栏当时**没在响** —— 「凭证加密」与「端到端」两个套件在本机
//            因沙箱禁用了子进程而崩溃，那条判据根本没跑到。
//
//            削法：**队友名单 `envs[].members` 只留头条那一支**（`slimFrontierUnit`）。
//            原来 5 个副本各带一份（81 条 × 4 关 × 4 人 = **87.8 KB**，占整份 13%），
//            而「按阵容去重」只需要一支代表队伍 —— 抽卡方案的 `teamPoolUnits` 找的就是
//            「第一个带名单的 env」，其余 4 关那几份是纯重复。
//            ⚠️ **`members` 不能整条删**：整条删掉后 `teamPoolUnits` 拿不到队伍、
//            补金推荐整个空掉（实测 `team-plan-test` / `version-weight-plan-test`
//            当场红）—— 这是本轮唯一一次改错又改回来的地方。
//            剩下 4 关的名单由 `/api/archive/packs` 补：详情窗口打开时本来就要取一次，
//            `enrichTipDetail` 的 `needEnvs` 判据加了「缺 `members` 也要去取」这一条
//            （原来只看条数，条数齐的总榜整包永远不会被补齐）。
//
//            实测（`tools/_probe-merge-edge.mjs`，可复跑）：
//              1 档 492.8 KB / 3 档 570.0 KB / **6 档 596.2 KB** / 9 档 629.1 KB /
//              **12 档 638.1 KB** —— 比四个分支合进来**之前**（649.6 KB）还小 53 KB。
//            `e2e-test` 因此**新增一条**「12 档也得在上限内」的判据：
//            原来那条只测默认 6 档，而档位数现在由用户控制，两端都要钉住。
//
//   v4.6.119 2026-10-17 晚：**强度只看行动值** + 「已登场却无证据」改成继承
//            （用户原话：「强度得分应仅考虑强度（不考虑别的，因此低难副本普遍能拿满分）」、
//            「如果已登场却无证据，一个高成本角色自动继承其低成本角色的得分，因为人们
//            一般不会上传低难度关卡用超高成本通关的记录」）：
//
//            起因是用户问「为什么 E6 的强度这么低」。逐层拆（`_probe-e6-strength.mjs`，
//            复刻与真实输出最大偏差 0.0001）后发现不是档位被歧视 —— E6 中位 18.3 其实
//            是四档最高 —— 而是三处相乘：
//              * **顶格档按金数折**：`100 × 该期最省金 ÷ 本队金数`。混沌 / 虚构的「最省
//                0 行动值队」只要 **1~3 金**，18 金的 E6 队只拿 6~17 分；绝境 floor 是
//                29~48 金才有 45~67。于是 E6 的分**几乎全部来自绝境一关**（权重 5）。
//              * **已登场却无证据**：E6 每个副本平均 2.35 个版本「已登场却没人上传」
//                （E0 1.73），按旧口径算 0 分、权重还进分母 —— 等于乘 0.57。
//              * **分母固定是全部 5 个副本**（权重和 9），E6 平均只覆盖 2.90 关。
//
//            ① **金数彻底退出强度**：
//               `0 行动值 → 100`、`否则 → 90 × 判据线曲线(行动值)`。
//               删掉两处折分（顶格档的金数比、第二档的 `min(90, 100×最省÷最贵)`），
//               `zeroAvGoldBySeason` 不再被强度读取（字段仍下发，探针复算历史口径要用）。
//               角色总榜（`frontierBoard`）与抽卡方案（`teamPlan` 的 `withStrength`）
//               **两条链一起改**，两个榜的强度口径不许分叉。
//               ⚠️ 低难副本因此**普遍拿满分**，用户明确接受。
//            ② **已登场却缺证据 → 继承**：同角色、成本**严格更低**、且那一期那一关
//               自己打出了成绩的整包里取**最高分**（`cheaperPoolBySeason` /
//               `inheritedStrengthOf`）。只从「自己有实测证据」的整包继承、**不做链式
//               传递**；成本相等不算更便宜；「更便宜」按原始整包金数（隐金前）。
//               继承不到（同角色所有更便宜版本也没成绩）→ 仍算 0 分、权重进分母
//               （2026-10-10 那条保留，用户本轮再次确认）。
//               ⚠️ 继承**只作用于强度**，性价比仍按 0 分算。
//            ③ 新增字段 `inheritedSeasons`（整包级；逐副本的不下发 —— 397 个组合 ×
//               25 字节会把 660 KB 硬上限顶破，实测 661 KB），详情窗口据此写一句
//               「其中 N 个版本的分是继承来的」。
//            实测（榜上 261 个整包）：E6 强度中位 **18.3 → 48.3**、E0 **9.4 → 26.9**；
//            单关满分率 混沌 58~82% / 虚构 30~59% / 异相普通 47~70% / 绝境 0%；
//            继承覆盖 162 / 261 个整包、930 个「整包×副本×版本」段。
//            ⚠️ **整包强度 100 仍 0 条**：要 5 个副本 × 窗口内每一期都 0 行动值。
//               「低难副本普遍满分」说的是**单关**，不是整包 —— 别再当成 bug 查。
//            ⚠️ `strength-invariant-test` 按新口径重写（23 项），并新增四条继承判据。
//
//   v4.6.119 2026-10-17：**角色性价比第二轮**——上一版（v4.6.118）把口径改成了「配装」，
//            但**成本信号只占了 5% 的方差**，这一版把它做实，并修掉两个会让界面说谎的坑。
//
//            审计（261 个整包 / 81 个角色，`tools/_probe-cost-decomp.mjs`）：
//              * 成本项只解释性价比方差的 **5.0%**（强度单独 R²=0.558、两者合计 0.769）
//                —— 一个叫「角色性价比」的分项，方差的九成还是**强度**；
//              * `Spearman(性价比, 强度) = 0.866`、Pearson 0.747；
//              * 同角色「|Δ强度| ≤ 1」的 42 组里 **6 组（14.3%）**更贵的整包性价比反而
//                更高 —— `docs/功能要求.md` §8 第 39 条那条不变式等于没成立；
//              * 组均值 1 金 17.7 / 2~3 金 14.4 / ≥4 金 10.3，而强度是 11.3 / 16.2 / 24.1
//                —— 贵 4 倍性价比只掉 42%，强度却涨 113%。
//
//            ① **整包系数指数 0.5 → 1.0**（`SCORING.ownGoldFactorPower`）：同成绩违反率
//               14.3% → **10.3%**、与强度的 Spearman 0.866 → **0.741**。
//               ⚠️ 1.5 能到 2.4% 但 E6 只剩 0.6 分，太狠，不用。
//            ② **性价比刻度加一次开平方**（新增 `SCORING.costScorePower = 0.5`）：
//               原始量跨 **1623 倍**（0.40 ~ 644.2），线性 min-max 把中位压到 **7.6**、
//               **57.5%（150/261）不到 10 分**，100 分锚点由**单个**离群整包决定。
//               开平方后中位 **20.0**、<10 分的降到 **28.4%**，E6 档中位从 1.6 回到 **11.7**。
//               三个候选实测（`_probe-cost-transform` / `_probe-cost-clip`）：log1p 抬得太狠，
//               p5/p95 裁剪会把性价比的实际影响力顶到 **54%**（名义 40）—— 都不能用。
//               ⚠️ 代价是实际影响力 41.1% → 44.4%（+3.3pp），**已知并接受**；要抹平只能连
//                  强度一起做 σ 对齐，那会推翻「强度是绝对刻度」（用户 2026-10-14）。
//            ③ **界面验算链断裂（真 bug）**：`ownGoldFactor` 用 `rawGold`（隐金前），而
//               `advice-view.js` 印的除数是 `unit.gold`（隐金后）—— 开满隐金后 **67/261 条**
//               还原不出印出的系数，还出现「1 ÷ 0」（罗刹 E6S1 印 1÷0、实际 0.354）。
//               修法：载荷新增 `ownGold`（原始金数），界面用它当分母。
//            ④ **角色面板那条投影漏了字段（v4.6.118 漏改）**：`archiveCharacterPacks` 的
//               投影与 `slimFrontierUnit` 本该逐字段等价，却没带 `ownGoldFactor` /
//               `ownGoldRef` —— 从面板打开的性价比来源表会把系数静默当成 1，
//               「Σ贡献 × 系数 = 合计」在那里对不上。已补齐。
