//               一个都不进）。查证后**不是 bug** —— 整包在构造时就折过档
//               （`packKeyOf` / 整包行都过 `eidolonTierOf`，`unit.eidolon` 只可能是
//               0/1/2/6），所以那一句是幂等的。仍然改成同样过 `eidolonTierOf`：
//               把「本表只收本桶」写成代码，防的是上游哪天改存原始级数时整批消失。
//               界面的兜底筛选（`unitListOf`）同改，两处判据必须同一套。
