//
//   v4.6.119 2026-10-17：**角色泛用性的算法修复**（用户「你负责分析并修复角色泛用性的
//            算法，先检查目前的情况」；追问后拍板「尺子换分位夹逼」+「连缺副本口径一起修」）。
//            分支 `fix/versatility-algorithm`，worktree 在 `.worktrees/fix-versatility-algorithm`。
//
//            诊断（新增 `tools/_probe-vers-diagnose.mjs`，全部走生产同一条取数路径）：
//
//            ① **尺子是裸 min-max，被单个离群值撑满**。低档组 36 个限定角色 / E6 组
//               50 个，榜面 180 条低档整包里 **126 条 ≤10 分**、中位 **3.8**，90 分以上
//               只有 **3 条**（知更鸟原始量 6.01，第二名 2.99）—— 泛用性在角色得分里
//               权重 0.2，实际对 95% 的角色恒为 0~2 分，这一维等于没生效。E6 组同病
//               （81 条里 55 条 ≤10 分、中位 2.0）。
//            ② **跨副本分母是「全部副本权重和」**（照抄强度那一侧的「缺副本按 0」，
//               注释里写着「同一个反向激励根治点」）。可那论据属于强度：强度量成绩，
//               没成绩确实是差；泛用性量关系网，没投稿 ≠ 不百搭。实测原始量中位随
//               「有数据副本数」单调爬升：**1 个 0.169 / 2 个 0.385 / 3 个 0.463 /
//               4 个 0.703 / 5 个 1.044** —— 只投 1 个副本的角色天生只能拿 1/9 上限。
//            ③ **低档组三档平均**（用户 2026-10-16 第 3 条，本轮**保留**）：`原始量 ÷ E0
//               本档值` 中位只有 0.59（p25 0.46 / p90 1.31），E1/E2 的稀疏投稿把平均值
//               摊薄了。已写进文档留作下一个决策，本轮不动。
//
//            修法：
//              ① 新增 `SCORING.versatilityExtentTrim = 0.05` 与 `versatilityExtentTrimMinSamples
//                 = 20`，加模块级 `versatilityExtentOf()`：两组尺子的端点改成 **p5 / p95**，
//                 超出由既有 `clamp(0,1)` 夹到 0/100；样本 < 20（测试夹具）退回 min/max。
//                 为什么是 0.05 不是 0.1：0.1 会把知更鸟 / 千冶•刃 / 风堇一起压成并列 100，
//                 区分度反而丢在最该区分的头部。
//              ② 取样**按角色去重**。原口径没有这一步（min/max 不受重复影响），但换成
//                 分位之后它会变成偏差：同一角色同组的所有整包带同一个原始量，不去重
//                 等于给「配装多的角色」重复计票。
//              ③ `versatilityPerTier` 的分母改成「该整包有数据的那些副本」的权重和
//                 （`versaWeight`）。关卡权重仍在分子里 —— 用户 2026-10-16 第 4 条
//                 「不能因为某角色在低权重关卡泛用就当成高权重关卡也泛用」不受影响。
//              ④ 队级 `teamPlan` 的 `groupExtents` 兜底改走同一个 `versatilityExtentOf`，
//                 并按 `isVersatilityIgnored` 跳过「不用抽就有」的角色 —— 旧兜底没跳，
//                 lo 会被那些恒 0 的角色拉到 0，与总榜分叉（恒等式会当场对不上）。
//              ⑤ 界面：泛用性的区间文案从「榜内 最小 ~ 最大」改成「组内 5%~95% 分位」，
//                 来源块脚注写「超出按 0 / 100 夹逼」。照旧写「榜内」会让读者拿最高分
//                 角色验算出 >100。
//
//            实测（修前 → 修后）：低档组原始量中位 0.51 → **1.67**、榜面中位分 3.8 → **4.1**、
//            p90 30.8 → **60.3**、90 分以上 3 条 → **9 条**；E6 组原始量中位 0.79 → **1.76**、
//            中位分 2.0 → **7.7**、p90 30.4 → **56.1**；「随副本覆盖数的爬升」6.2 倍 → **3.0 倍**。
//
//            边缘测试：
//              * A：`herta-test` **116 项**全绿（新增 2 条 ⭐：① 尺子对离群值免疫 ——
