//                ② 只投一个副本不被除小 —— 旧口径会得到 4/6 = 0.667，现在是 4）。
//                `team-plan-test` 40 项、`e2e` 193 项同样全绿（三档平均、两组尺子、
//                队级恒等式都没被这次改动破坏）。
