//
//            审计先摆事实（261 个整包 / 15604 条前沿行）：
//              * `r(强度得分, 性价比得分) = 0.926`、Spearman 0.956、前 20 名重叠 15/20
//                —— 两个分项在量几乎同一件事，名义 40/40/20 实际是 **35/48/17**；
//              * `r(整包自己的金数, 性价比得分) = 0.030` —— 一个叫「角色性价比」的分项
//                与「这个配装贵不贵」几乎无关（金数项的分母是**队伍**金数）。
//
//            ① **加「整包自身金数」系数**（用户选项 D）：
