//
//            根因是**同一个界面里有两条按版本加权的链，读了不同的表**：
//              * `archiveFrontier`（性价比总榜 / 角色得分 / 跨版本发挥 / 详情窗口）
//                —— 一直吃用户在界面上设的那份；
//              * `resolveScope` → `aggregateTeams`（跨版本聚合的阵容表 + `buildAvTeams`
//                的行动值前沿池）—— 这一层**写死了** `VERSION_WEIGHTS`，而**抽卡方案的
//                候选池正是它的两个来源**（证据池 ∪ 0 行动值前沿池）。
//            于是「总榜动了、方案纹丝不动」。两处修：
//              ① `resolveScope` 改读 `normalizeVersionWeights(options.versionWeights)`
//                 —— `weightOf`（逐版本加权）与回显的 `versionWeights` 都跟着用户表；
//              ② `conclusionEnvs()` 把 `versionWeights` 透传给 `archiveTeams()`
//                 —— `/conclusion` 与 `/api/archive/packs` 两条入口都带上。
//            顺带堵掉前沿池选行的**兜底泄口**：`avRowFor` 原来在「窗口内一个有权重的
//            版本都没有数据」时退回 `newestAv`，而那一版恰恰可能是用户清零的那一版 ——
//            于是「把某几版权重调成 0」在方案里同样看不出效果（实测 `[1,0,0,0,0,0]` 与
//            默认表的 `avTeams` 逐字相同）。现在只有**夹具**（没有 `bySeasonAv`）才准
//            走 `newestAv`；生产形状下「窗口内没有有权重的版本」= 这个阵容不进池。
//            实测（空账号 + 仓库内真数据集）：默认表 / 六版等权 / 只要当前版本，方案名单
//            三次全不同，强度分在这一档里从 16.7·27.8 挪到 8.3·24.2·27.8。
//            ⚠️ **默认表下的输出逐字不变**（`avTeams` / `teams` 与改前一致）——老调用、
//            老存档的用户看到的方案分毫不差，只有「改过版本权重」的人才会看到变化。
//            回归：新增 `tools/version-weight-plan-test.mjs`（13 项，离线）——
//            钉「回显、`avTeams` 选行、`teams` 加权、`conclusionEnvs` 透传、
//            `teamPlan` 名单与强度、两条链都只认一个版本」。
