//               第 3 条要的形状）：每组各占一行输入框 + 一行摘要，整块约 300px。
//               现在 `.advice-weights-groups` 是 `repeat(3, minmax(0, 1fr))`，组内的
//               输入框再分两小列（5 / 3 / 6 个旋钮 → 3 / 2 / 3 行），三组的摘要各自
//               压在列底（`margin-top: auto`），整块降到约 240px（实测 1500px 视口：
