//               属性按游戏内七色上色（CSS `.char-el[data-element=…]`，JS 只给键不给色板）。
//               实测（three_char 夹具 + 一个「characters 里删掉 path/element、只留
//               index.avatar_list 的 element」的探针夹具）：**刃 = 毁灭·风属性**、
//               **开拓者 = 毁灭·物理属性**、**三月七 = 存护·冰属性** —— 三条兜底各走了一遍。
//
//            边缘测试：`node tools/run-tests.mjs` **21 个套件全绿**（e2e 193 / herta 113 /
//            team-plan 39 / 强度不变式 10；CDP 套件本机未开浏览器，按惯例跳过并做语法自检）；
//            另用 `tools/check-advice-layout.mjs --url=http://127.0.0.1:8399/`（GUI 夹具 +
