//            隐金设置住在② 综合结论开头」两处几何判据。
//
//   v4.6.116 用户 2026-10-17 的**评分口径两改 + 全站排版统一**（分支 `main`）：
//
//            ==== 一、强度口径重做（用户第 2、3 条）====
//            旧口径是「行动值 + 投入加成」的合成：同一个 0 行动值的配装，花 48 金的
//            与花 12 金的能同分，用户报「高造价必然等于高强度」不成立。
//            新口径（五个副本同一套，绝境王棋关以**行动值**为单位、末日幻影折成
//            `a = 4000 − 积分`、其余关用轮次）：
//              * **顶格档**（这一期真的有人打出 `a === 0`）：`100 × 最省金 ÷ 本队金数`
//                —— 最省金那支拿 100，其余**等比降分**；
//              * **非顶格档**（48 金也打不出 0）：沿用判据线曲线，**封顶 90**
//                （用户确认「低于 100」的一层，不是额外一档）；
//              * 两档都**不跨版本比较**：`a === 0` 的判定与「最省金」都按版本各算
//                （服务端新字段 `zeroAvGoldBySeason`），跨版本累加时用用户设的版本权重。
//            实测（theherta）：`aa/plight` 各期最省金 48/48/48/29/48 金，`as` 从
//            4.1 的 44 金一路降到 4.6 的 5 金；整包强度 = 100 的一条都没有，
//            top10 上限 70.2 —— 90 分的天花板在整包层从未触发。
//            ⚠️ 踩坑：一度按行动值挑代表行（`pack.avSeason`），实测与用 `observed`
//            只差 1 个整包却**回归了用户报过的 bug**，已回退并注释「不许改回去」。
//
//            ==== 二、泛用性改成两组各自归一（用户第 1 条）====
//            「E6 角色仅与 E6 比、E0/E1/E2 与 E0/E1/E2 比，避免不同量级之间的比较」。
//            原始量本身是「按版本/关卡加权的不同队友数」，E6 出现在更少的投稿里 ⇒
//            原始量系统性偏低（实测候选池成员位：E6 组 0.21 vs 低档组 1.63）。
//            做法：每个角色先按 `角色|E档` 求**组均值**（低档组 = 三档各平均再对档平均；
//            E6 组 = E6 那一档的平均），再用**两把尺子**分别 min-max：
//              * 角色级：`versatilityGroupOf` / `versatilityExtentOfGroup`，
//                `frontierExtents.versatility` 的 `lo/hi` 给低档组、`byTier[6]` 给 E6 组；
//              * 队级：`teamPlan()` 里 `groupExtents` + `memberVersatilityScore`，
//                成员先按自己那一组归一，再按**成本占比**加权（用户 2026-10-14 第 1 条）。
//                恒等式：队级 ③ = 成员们在总榜上泛用性分的成本加权平均。
//            实测：榜上全部 261 个 `角色|E档` 去重后，两组**组内相对分均值
//            10.1（低档）/ 10.7（E6）**—— 持平，量级差确实被抹掉了
//            （`tools/_probe-vers-shape.mjs`）。
//            ⚠️ 中位数仍差一截（4.6 vs 2.7）：E6 那把尺子的上界被知更鸟 E6（7.22）
//            独自撑高，min-max 对离群值敏感。这是**已知特性**，不是回归。
//
//            ==== 三、全站排版统一（三个子智能体并行审查的结论）====
//            ① **「查看来源」内联按钮被钉到详情窗口右上角**（高）：`.advice-detail-toggle
//               .is-inline` 有一条全局 `position:absolute`，4 个按钮全都飞到 `.modal`
//               右上角。改成默认回流内，只有 `.advice-factor-cell` 里的那一枚顶到右边
//               （等宽 padding 是「文字居中」与「按钮在右」能同时成立的原因）。
//            ② **方案卡等式是唯一的硬溢出源**（高）：`.advice-plan-team-eq` 的
//               `white-space:nowrap` 在窄屏把卡片撑破。改 `overflow-wrap:anywhere`。
//            ③ **「已有 / 缺」三套写法**：总榜行与环境统计用 `.advice-own-badge`（绿 pill），
//               方案卡用自己一套 `.advice-plan-team-own`（青 / 红 pill）—— 并排就成了
//               「三种已有」。统一到 `.advice-own-badge` + `is-gap`，并从「槽位最右边」
//               挪到**角色名后面**（⚠️ 必须单独包一层 flex 行：label 是 grid，直接
//               append 会让徽标独占一行）。
//            ④ **数字格式与措辞 9 处**：合计行进 `packScoreText`；「判据线内」→
//               「已达判据线」；两处来源表头「权重」→「关卡权重」（避免与抽卡权重混）；
//               方案卡 facts 与最佳证据改走 `goldText()`、补档位、语序改「行动值 N」、
//               缺数据不画（修「— 金」破折号吊单位）；泛用性脚注 lo/hi 走 `.toFixed(1)`。
//            ⑤ **结构一致性**：总榜 h4 补 `.advice-section-head` 外壳（CSS 加
//               `.advice-section-head .advice-h4{margin:0}`）；`.advice-plan-team-best`
//               显式钉 11.5px，消掉 facts 行内 12.5 与 11.5 并排。
//            ⚠️ 审查中**明确不做**的（面太大或需产品决策）：不反转深色主题（仓库本来就是
//               深空主题）、不删约 250 行死 CSS、不收敛 7 套断点、不建 `--space-*` 间距
//               变量、不动视频入口在总榜行与方案卡的深度不一致。
//
//            边缘测试：
//              * **A 无依赖**：全套 **21 个套件通过**（`herta-test` / `team-plan-test`
//                / `e2e` / 强度不变式……）。泛用性与队级那几条**整条重写为两组口径**：
//                `herta-test` 断言 E6 用自己那份、E0/E1/E2 用三档平均；`e2e-test` 三条
//                反过来钉「E0/E1/E2 相同、E6 不同」「`byTier` 的 0/1/2 同值、6 不同值」
//                「packs 顶层 `versatilityRaw` 与该档 raw 严格相等」；`team-plan-test`
//                新增 `carrierE6`（charX E6 无光锥）与 `carrierLow`（charX E2 + coneB S4）
//                —— **金数相同、只差星魂档**，断言两者都 87.5、③ 不许凭空变高。
//              * **C 需 9222 调试浏览器**：`check-advice-layout` 本机没起浏览器，
//                只跑了跳过时的语法自检（`node --check` 两个文件均通过）。
//              * 新增 `tools/_probe-vers-shape.mjs`（两组分布形状 + 归一后是否持平）。
//
//   v4.6.115 用户 2026-10-17 的**界面显示改进五条**（分支 `main`，一轮做完）：
//
//            ① **权重栏放在综合结论下方**：`#adviceFrontierWeights` 与
//               `#adviceHiddenCostsBar` 从「角色总榜」标题之下**整块搬到「② 综合结论」
//               这一节的开头**（追问确认：**两块一起移**）。改前它们读起来像「总榜自己的
//               设置」，可关卡权重与抽卡权重**同时喂角色总榜与抽卡方案**、隐金设置改的也是
//               总榜的账面金数 —— 摆在那一节的开头才是「先看到旋钮，再看两个榜」。
//
//            ② **角色总榜三个分项改名**：「强度 / 性价比 / 泛用性」→
//               **角色强度 / 角色性价比 / 角色泛用性**（`partSources` / `scoreBreakdownTable` /
//               分割标题 / 三个来源块标题）。⚠️ **抽卡权重那三个输入框刻意不改**（追问确认：
//               保持「强度 / 性价比 / 泛用性」）—— 它们是两个榜**共用**的一组系数，
//               加「角色 / 队伍」前缀会被读成只管某一个榜。
//
//            ③ **角色得分详情窗口的分项排版**：改前 `.advice-factor-cell` 是
//               `flex + space-between`、`.tip-stack` 又是 shrink-to-fit 的 inline-flex，
//               于是三行的文字块中心**随说明那一行的长度漂**（实测 364 / 301 / 389），
//               既不在一条竖线上、也对不上表头「分项」的中心（579）—— 用户报的
//               「分项的排版有误，请对齐标题」。追问确认是「**两项都居中**」。
//               修法：整格改成 `display:block` + **左右等宽** `padding: 0 76px`，
//               `.tip-stack` 铺满并居中，「查看来源」按钮 `position:absolute` 顶到右边
//               （等宽 padding 是「文字居中」与「按钮在右」能同时成立的原因）。
//               实测三行中心 = 593 / 593 / 593，与表头 593 重合（判据 ≤ 4px）。
//
//            ④ **补金推荐三个分项改名**：「强度得分 / 性价比 / 泛用性」→
//               **队伍强度 / 队伍性价比 / 队伍泛用性**（三项统一加前缀、去掉「得分」二字；
//               追问确认）。落点：卡片等式、三条 meter、`planScaleTable()` 三行、
//               `teamPlanTip()` 的等式与四条说明、方案脚注。
//
//            ⑤ **抽卡方案所有队伍都要有视频链接**（用户原话「类似角色总榜」）。
//               根因实测：15 张卡只有 **7 张**有视频，缺的 8 张**全是行动值前沿池**
//               （`avTeams`）的队伍 —— 建库侧的前沿行只有 `{c,a,t,m}` 四个键、
//               本来就没有投稿地址，而这一池恰恰是「0 行动值满配队」的唯一来源，
//               于是 v4.6.110 之后**前排全是点不出视频的卡片**。
//               修法与 `archiveFrontier` 同一口径：服务端按 `版本|阵容` 回查
//               `teams[].sample.video`（新索引 `sampleVideoByRosterSeason`，只在
//               `withFrontier` 时才建），挂到 `bySeasonAv` / `newestVideo` 上，
//               再由 `avRowFor` **跟着被版本权重挑中的那一版**带出来（不借别的版本
//               —— 那会把行动值与视频拼成两条不相干的投稿）。
//               实测：5 个副本 × 8 条 = **40/40**；界面 **15/15** 张卡都有。
//
//            边缘测试：
//              * A：`node tools/run-tests.mjs` 全套 **21 个套件通过**
//                （`herta-test` 113 / `team-plan-test` 39 / `e2e` 192 / 强度不变式 10）。
//              * C：`check-advice-layout` **通过**（新增 3 条判据：权重栏位置、三分项居中、
//                方案卡 15/15 视频；同步改掉 4 处写死的旧标签断言：`SPLIT_LABELS`、
//                卡片等式的 `numAfter/coefAfter`、`rowLabels`、泛用性来源块前缀）。
//              * 新增 `tools/_probe-av-video.mjs`（走 `conclusionEnvs`，与生产同一条取数路径）。
//
// 注意与 src/mihoyo/constants.js 的 APP_VERSION 区分：那个是**米游社客户端**的
// 版本号（2.109.0），用来和 salt 配套签名请求，和本工具的版本毫无关系。

/** 本工具版本（包内唯一来源，package.json 的 version 与此保持一致）。 */
//   v4.6.136 2026-10-21：**上场率 · 环境统计的两处口径与呈现**（分支 `feat/usage-stats`）。
//
//            * **透传真实投稿数**：`archiveUsage()` 把 frontierRows 映射成统计行时漏了
//              `n`（`archive.js` 的 `submissions`），环心印的「条投稿」一直是**配装行数**
//              —— 实测 17242 条投稿被印成 15604（少 9.5%），绝境 0 行动值 50 条被印成
//              25（少一半）。与 v4.6.134 在 `gacha-plan-run.js` 修掉的是同一类 bug。
//            * **非通关档带 `shareOfClear`**（占通关的比例）：四档是切分与嵌套
//              （轮次型通关 = 0T+1T+2T 精确加总；0 行动值 ⊂ <300 行动值），并排的
//              Σ=100% 环形图极易被读成互斥四类；UI 在卡片标题旁印「占通关 x%」
//              挑明这层结构，顺带提示「这两张饼几乎一样」（末日 <300 占 99.8%）。
//            * 说明区补「读图」一条；环心注释的样本数由行数更正为真实投稿数。
//
export const PROGRAM_VERSION = '4.6.137';

/** 对齐的游戏版本。 */
export const GAME_VERSION = '4.6';

/** 显示用标签。 */
export const VERSION_LABEL = `v${PROGRAM_VERSION}`;

/** 页脚/日志里的一行说明。 */
export const VERSION_TEXT = `${VERSION_LABEL}（对齐游戏 ${GAME_VERSION}）`;
